const DATA={"functions":[{"name":"print()","desc":"يعرض قيمة على الشاشة.","code":"print(\"Hello\")","result":"Hello"},{"name":"max()","desc":"يعيد أكبر قيمة.","code":"max([3, 7, 1])","result":"7"},{"name":"min()","desc":"يعيد أصغر قيمة.","code":"min([3, 7, 1])","result":"1"},{"name":"abs()","desc":"يعيد القيمة المطلقة دون إشارة سالبة.","code":"abs(12 - 40)","result":"28"},{"name":"pop()","desc":"يحذف عنصرًا بفهرسه ويعيد العنصر المحذوف.","code":"mlist = [5, 8, 7]\nmlist.pop(0)","result":"5","after":"[8, 7]"},{"name":"sorted()","desc":"يعيد قائمة جديدة مرتبة، ولا يغيّر الأصل.","code":"sorted([8, 7])","result":"[7, 8]"},{"name":"sum()","desc":"يجمع عناصر القائمة العددية.","code":"sum([10, 20, 30])","result":"60"},{"name":"len()","desc":"يعيد عدد الأحرف أو العناصر.","code":"len(\"Ali\")","result":"3"},{"name":"range()","desc":"يولّد أعدادًا من البداية إلى ما قبل النهاية.","code":"list(range(5, 10, 2))","result":"[5, 7, 9]"},{"name":"round()","desc":"يقرّب العدد؛ وعند تعادل النصف يختار العدد الزوجي الأقرب.","code":"round(27.6)","result":"28"},{"name":"append()","desc":"يضيف عنصرًا في نهاية القائمة.","code":"k = []\nk.append(\"Ali\")\nprint(k)","result":"['Ali']"},{"name":"input()","desc":"يقرأ إدخال المستخدم كنص دائمًا.","code":"txt = input(\"Name: \")\n# إدخال: Ali\nprint(type(txt).__name__)","result":"str"},{"name":"int()","desc":"يحوّل نصًا عدديًا مناسبًا إلى عدد صحيح.","code":"int(\"20\")","result":"20"}],"lessonChecks":{"types":{"id":"check-types","topic":"types","prompt":"ما نوع المتغيّر c؟","code":"c = input(\"Name: \")","options":["int","str","bool","list","float"],"answer":"str","explanation":"input() تعيد نصًا دائمًا. للحصول على عدد صحيح نستخدم int(input(...)).","marks":1},"operations":{"id":"check-operations","topic":"operations","prompt":"توقّع ناتج البرنامج.","code":"x = 28\nc = x // 3\nprint(c)","options":["9","9.33","1","10"],"answer":"9","explanation":"28 ÷ 3 تساوي 9 والباقي 1؛ القسمة الأرضية تعيد 9.","marks":1},"flowcharts":{"id":"check-flowcharts","topic":"flowcharts","prompt":"أي شكل تختار للشرط sm < 100؟","options":["معيّن","مستطيل","بيضاوي","متوازي الأضلاع"],"answer":"معيّن","explanation":"الشرط قرار، لذلك نستخدم المعيّن مع مساري Yes وNo.","marks":1},"conditions":{"id":"check-conditions","topic":"conditions","prompt":"عند sm = 100، ما قيمة الشرط؟","code":"sm < 100","options":["True","False"],"answer":"False","explanation":"100 تساوي 100 ولا تقل عنها. لو استخدمنا <= لأصبح الشرط True.","marks":1},"functions":{"id":"check-functions","topic":"functions","prompt":"ما الناتج؟","code":"a = [5, 8, 7]\na.pop(0)\nprint(sorted(a))","options":["[7, 8]","[5, 7, 8]","[8, 7]","5"],"answer":"[7, 8]","explanation":"نحذف العنصر الأول 5، ثم نرتّب ما تبقى: [7, 8].","marks":1},"loops":{"id":"check-loops","topic":"loops","prompt":"كم مرة تُنفَّذ الأوامر داخل هذه الحلقة؟","code":"for i in range(5, 10, 2):\n    print(i)","options":["2","3","4","5"],"answer":"3","explanation":"تأخذ i القيم 5 ثم 7 ثم 9، لذلك تُنفَّذ الحلقة ثلاث مرات. النهاية 10 غير مشمولة.","marks":1}},"lessonFor":{"types":"types","operations":"operations","flowcharts":"flowcharts","conditions":"conditions","functions":"functions","loops":"loops","errors":"functions"},"lessons":[{"id":"types","title":"أنواع البيانات","en":"DATA TYPES","description":"تعرّف على القيم التي يتعامل معها بايثون، واختر النوع الصحيح.","minutes":6,"icon":"database"},{"id":"operations","title":"العمليات الحسابية","en":"OPERATIONS","description":"جرّب العمليات وشاهد الفرق بين القسمة وباقي القسمة.","minutes":5,"icon":"calculator"},{"id":"flowcharts","title":"الخرائط التدفقية","en":"FLOWCHARTS","description":"حوّل خطوات الحل إلى مسار واضح، وابنِ خريطتك بنفسك.","minutes":8,"icon":"workflow"},{"id":"conditions","title":"الشروط واتخاذ القرار","en":"CONDITIONS","description":"غيّر القيم واكتشف كيف يختار البرنامج المسار المناسب.","minutes":5,"icon":"split"},{"id":"loops","title":"التكرار باستخدام for","en":"LOOPS","description":"افهم كيف يكرّر for الأوامر، وتتبّع القيم في كل دورة.","minutes":7,"icon":"repeat"},{"id":"functions","title":"الدوال المهمة","en":"FUNCTIONS","description":"دوال صغيرة تختصر خطوات كثيرة. جرّبها وافهم نتائجها.","minutes":10,"icon":"code"}],"mockQuestions":[{"id":"mock-1","topic":"types","prompt":"ما نوع المتغيّر x؟","code":"x = 42","options":["int","float","str","bool"],"answer":"int","explanation":"42 عدد صحيح بلا جزء عشري.","marks":2,"kind":"choice"},{"id":"mock-2","topic":"types","prompt":"ما نوع القيمة التي تعيدها input()؟","code":"x = input(\"Age: \")","options":["int","str","float","list"],"answer":"str","explanation":"input() تعيد نصًا، حتى عند إدخال أرقام.","marks":2,"kind":"choice"},{"id":"mock-3","topic":"types","prompt":"ما نوع المتغيّر r؟","code":"r = 8 / 2","options":["int","float","bool","str"],"answer":"float","explanation":"القسمة / تعيد 4.0 من النوع float.","marks":2,"kind":"choice"},{"id":"mock-4","topic":"types","prompt":"ما نوع المتغيّر y؟","code":"x = [10, False, \"A\"]\ny = x[1]","options":["list","int","str","bool"],"answer":"bool","explanation":"الفهرس 1 يشير إلى العنصر الثاني: False.","marks":2,"kind":"choice"},{"id":"mock-5","topic":"flowcharts","prompt":"أي شكل يمثّل اتخاذ قرار؟","code":"","options":["مستطيل","معيّن","بيضاوي","سهم"],"answer":"معيّن","explanation":"المعيّن يختبر شرطًا ويفرّع المسار.","marks":2,"kind":"choice"},{"id":"mock-6","topic":"flowcharts","prompt":"أي شكل يمثّل الإدخال والإخراج؟","code":"","options":["متوازي الأضلاع","مستطيل","معيّن","دائرة"],"answer":"متوازي الأضلاع","explanation":"يستخدم متوازي الأضلاع لقراءة البيانات وعرضها.","marks":2,"kind":"choice"},{"id":"mock-7","topic":"flowcharts","prompt":"أي مسار نتبع عند sm = 100؟","code":"sm < 100","options":["Yes","No"],"answer":"No","explanation":"100 ليست أصغر من 100، فالشرط False.","marks":2,"kind":"choice"},{"id":"mock-8","topic":"operations","prompt":"ما الناتج؟","code":"17 // 4","options":["4.25","4","1","5"],"answer":"4","explanation":"القسمة الأرضية تقرّب الناتج إلى الأسفل.","marks":2,"kind":"choice"},{"id":"mock-9","topic":"operations","prompt":"ما الناتج؟","code":"17 % 4","options":["4","0","1","4.25"],"answer":"1","explanation":"17 = 4 × 4 + 1؛ الباقي 1.","marks":2,"kind":"choice"},{"id":"mock-10","topic":"conditions","prompt":"ما الذي يُطبع؟","code":"n = 20\nif n >= 20:\n    print(\"A\")\nelse:\n    print(\"B\")","options":["A","B","True","20"],"answer":"A","explanation":"20 أكبر من أو تساوي 20، فننفّذ if.","marks":2,"kind":"choice"},{"id":"mock-11","topic":"functions","prompt":"ما الناتج؟","code":"abs(9 - 25)","options":["-16","16","34","9"],"answer":"16","explanation":"9 - 25 تساوي -16، والقيمة المطلقة 16.","marks":2,"kind":"choice"},{"id":"mock-12","topic":"functions","prompt":"ما الناتج؟","code":"len(\"Python\")","options":["5","6","7","Python"],"answer":"6","explanation":"النص يحتوي على ستة أحرف.","marks":2,"kind":"choice"},{"id":"mock-13","topic":"functions","prompt":"ما القائمة بعد التنفيذ؟","code":"a = [4, 9, 2]\na.pop(1)","options":["[9, 2]","[4, 2]","[4, 9]","[4, 9, 2]"],"answer":"[4, 2]","explanation":"يحذف pop(1) العنصر الثاني، وهو 9.","marks":2,"kind":"choice"},{"id":"mock-14","topic":"functions","prompt":"ما الناتج؟","code":"sum([6, 8, 11])","options":["11","3","25","14"],"answer":"25","explanation":"6 + 8 + 11 = 25.","marks":2,"kind":"choice"},{"id":"mock-15","topic":"loops","prompt":"ما الذي يُطبع؟","code":"x = 0\nfor i in range(2, 7, 2):\n    x = x + i\nprint(x)","options":["6","12","14","9"],"answer":"12","explanation":"القيم 2 و4 و6؛ مجموعها 12. النهاية 7 مستبعدة.","marks":2,"kind":"choice"},{"id":"mock-16","topic":"functions","prompt":"ما الناتج؟","code":"a = [9, 3, 6]\nprint(sorted(a))","options":["[9, 3, 6]","[3, 6, 9]","[9, 6, 3]","[3, 9, 6]"],"answer":"[3, 6, 9]","explanation":"sorted() تعيد نسخة مرتبة تصاعديًا.","marks":2,"kind":"choice"},{"id":"mock-17","topic":"operations","prompt":"ما الناتج؟","code":"x = round(19.7)\nprint(x // 3)","options":["6","7","6.67","20"],"answer":"6","explanation":"نقرّب أولًا إلى 20، ثم 20 // 3 = 6.","marks":2,"kind":"choice"},{"id":"mock-18","topic":"conditions","prompt":"ما الناتج؟","code":"m = max([11, 18, 15])\nif m < 18:\n    print(\"low\")\nelse:\n    print(m)","options":["low","15","18","11"],"answer":"18","explanation":"أكبر قيمة 18؛ الشرط 18 < 18 غير محقق.","marks":2,"kind":"choice"},{"id":"mock-19","topic":"errors","prompt":"ما التصحيح المناسب؟","code":"print(MAX([2, 5]))","options":["print(max([2, 5]))","print(Max([2, 5]))","print[2, 5]","لا يوجد خطأ"],"answer":"print(max([2, 5]))","explanation":"بايثون حساس لحالة الأحرف؛ الاسم الصحيح max.","marks":2,"kind":"choice"},{"id":"mock-20","topic":"errors","prompt":"ما التصحيح للحصول على 7؟","code":"txt = \"5\"\nprint(txt + 2)","options":["print(txt + \"2\")","print(int(txt) + 2)","print(txt * 2)","print(str(2))"],"answer":"print(int(txt) + 2)","explanation":"نحوّل النص إلى عدد صحيح قبل الجمع.","marks":2,"kind":"choice"}],"topicLabels":{"types":"أنواع البيانات","operations":"العمليات","flowcharts":"الخرائط التدفقية","conditions":"الشروط","functions":"الدوال والقوائم","loops":"تتبّع التكرار","errors":"اكتشاف الأخطاء"},"typeExamples":[{"value":"20","type":"int","label":"عدد صحيح","description":"عدد بلا جزء عشري، مثل العمر أو عدد الطلاب."},{"value":"3.5","type":"float","label":"عدد عشري","description":"قيمة تحتوي على جزء عشري."},{"value":"\"Ali\"","type":"str","label":"نص","description":"أحرف بين علامتي اقتباس، حتى لو كانت أرقامًا."},{"value":"True","type":"bool","label":"قيمة منطقية","description":"إحدى قيمتين فقط: True أو False."},{"value":"[10, 20, 30]","type":"list","label":"قائمة","description":"مجموعة عناصر مرتبة داخل أقواس مربعة."}],"errorExamples":[{"id":"original-6-1","code":"b = [14 ; 5, 9]\nprint(b)","tokens":["b",";","print"],"bad":";","why":"تُفصل عناصر القائمة بفواصل، لا بفاصلة منقوطة.","fix":"b = [14, 5, 9]\nprint(b)","replacement":","},{"id":"original-6-2","code":"txt = \"3\"\nn = txt + 2\nprint(n)","tokens":["\"3\"","txt + 2","print"],"bad":"txt + 2","why":"لا يمكن جمع نص وعدد صحيح مباشرة. التصحيح التالي أحد الحلول الصحيحة للحصول على جمع عددي.","fix":"txt = \"3\"\nn = int(txt) + 2\nprint(n)","replacement":"int(txt) + 2"},{"id":"original-6-3","code":"m = [12, 15, 14]\nprint(MAX(m))","tokens":["m","print","MAX"],"bad":"MAX","why":"أسماء الدوال حساسة لحالة الأحرف. الدالة المضمنة تُكتب max.","fix":"m = [12, 15, 14]\nprint(max(m))","replacement":"max"},{"id":"original-6-4","code":"for i in range 0,5:\n    print(i)","tokens":["for","range 0,5","print"],"bad":"range 0,5","why":"استدعاء range يحتاج إلى أقواس حول المعاملات.","fix":"for i in range(0, 5):\n    print(i)","replacement":"range(0, 5)"}],"originalGroups":[{"title":"الخريطة التدفقية","marks":4,"statement":"أكمل الإجراءات الناقصة في الخريطة التدفقية، لحل المسألة البرمجية التالية: تعيين القائمة Ltest وتحتوي على أربعة أرقام، إذا كان مجموع عناصر القائمة أقل من 100، يتم عرض الرسالة \"مجموع الدرجات أقل من 100\"، فيما عدا ذلك يتم عرض الرسالة \"انتبه، مجموع الدرجات تجاوز 100\"."},{"title":"أنواع البيانات","marks":5,"statement":"ضع علامة (✓) في الخانة المناسبة لنوع المتغيّر بناءً على الجمل البرمجية الآتية:"},{"title":"تتبّع التكرار","marks":5,"statement":"اقرأ البرنامج الآتي، ثم دوّن في الجدول قيم كل من المتغيّرات المبينة فيه عند كل تكرار:"},{"title":"توقّع المخرجات","marks":10,"statement":"اقرأ الأسطر البرمجية التالية، ونفذها ذهنيًا، ثم اكتب نواتج المخرجات في عمود Output:"},{"title":"إكمال الأكواد","marks":8,"statement":"أكمل الجملة التكرارية والجملة الشرطية لتنفيذ الهدف المطلوب من البرنامج."},{"title":"اكتشاف الأخطاء","marks":8,"statement":"تحتوي الأوامر الآتية على أخطاء، اكتب العبارة أو الحرف أو الرمز الذي تسبب بالخطأ:"}],"originalOutputs":[{"id":"original-4-1","topic":"functions","prompt":"المثال 1 · درجتان","code":"d1 = 12\nd2 = 40\nprint(abs(d1 - d2))","answer":"28","explanation":"نحسب 12 - 40 = -28، ثم abs(-28) تعيد 28.","marks":2},{"id":"original-4-2","topic":"operations","prompt":"المثال 2 · درجتان","code":"x = round(27.6)\nc = x // 3\nprint(x)\nprint(c)","answer":"28\n9","explanation":"round(27.6) تعيد 28؛ و28 // 3 تساوي 9. تُطبع كل قيمة في سطر منفصل.","marks":2},{"id":"original-4-3","topic":"functions","prompt":"المثال 3 · درجتان","code":"stn = [2, 1, 3]\nstn[0] = 4\nprint(\"New List :\", stn)","answer":"New List : [4, 1, 3]","explanation":"نغيّر العنصر الأول فقط إلى 4، ثم نطبع النص والقائمة. تفصل print بينهما بمسافة.","marks":2},{"id":"original-4-4","topic":"functions","prompt":"المثال 4 · درجتان","code":"mlist = [5, 8, 7]\nmlist.pop(0)\nprint(sorted(mlist))","answer":"[7, 8]","explanation":"يحذف pop(0) القيمة 5، ثم sorted تعيد [7, 8].","marks":2},{"id":"original-4-5","topic":"conditions","prompt":"المثال 5 · درجتان","code":"m = [13, 22, 14]\ns = max(m)\nif s >= 20:\n    print(\"max number is\", s)\nelse:\n    print(\"max less than 20\")","answer":"max number is 22","explanation":"max تعيد 22؛ وبما أن 22 >= 20 فإن مسار if هو الذي ينفّذ.","marks":2}],"originalTypes":["list","int","str","bool","float"],"originalTypesCode":"a = [\"Test1\", 20, True]\nb = int(input(\"Mark= \"))\nc = input(\"Name: \")\nd = a[2]\ne = b / 2","traceRows":[{"i":5,"x":45,"y":2},{"i":7,"x":38,"y":4},{"i":9,"x":29,"y":6}]};
