function assessmentReadyToSubmit(){if(!P.draft)return false;const qs=draftQuestions();return qs.length>0&&qs.every(q=>String(P.draft.answers[q.id]||'').trim());}
const button=(act,label,extra='',cls='button')=>{if(act==='submit-dialog'&&!assessmentReadyToSubmit())cls+=' secondary';return `<button class="${cls}" data-act="${act}" ${extra}>${label}</button>`;};
const input=(key,label,value='',type='text',extra='')=>`<input data-bind="${esc(key)}" aria-label="${esc(label)}" type="${type}" value="${esc(value)}" ${extra}>`;
