// 04. STORAGE UTILITIES — versioned, local-only and tolerant of invalid data.

// Authoritative learning progress and verified persistence; no schema changes.
const verifiedWrites=new Map(),failedWrites=new Set(),pendingWrites=new Set();
function getLearningProgress(){const ids=lessons.map(l=>l.id),completedIds=ids.filter(id=>P.completed.includes(id));return {completed:completedIds.length,total:ids.length,percentage:ids.length?Math.round(completedIds.length/ids.length*100):0,completedIds};}
function persistenceSnapshot(){return {state:failedWrites.size?'failed':pendingWrites.size?'pending':verifiedWrites.has(KEY)?'saved':'idle',verifiedAt:Math.max(0,...verifiedWrites.values()),failedKeys:[...failedWrites],pendingKeys:[...pendingWrites],progressSaved:verifiedWrites.has(KEY)&&!failedWrites.has(KEY)&&!protectedStoredProgress,readingPending:pendingWrites.size===1&&pendingWrites.has('tgn107.experience.v2'),protectedData:protectedStoredProgress};}
function announcePersistence(){const warning=document.getElementById('storage-alert');if(warning)warning.hidden=!storageError;window.dispatchEvent(new CustomEvent('tgn:persistence',{detail:persistenceSnapshot()}));}
function writeVerified(key,value){if(key===KEY&&protectedStoredProgress){failedWrites.add(key);storageError=true;announcePersistence();return false;}let ok=false;try{localStorage.setItem(key,value);ok=localStorage.getItem(key)===value;}catch{}pendingWrites.delete(key);if(ok){verifiedWrites.set(key,Date.now());failedWrites.delete(key);}else{verifiedWrites.delete(key);failedWrites.add(key);}storageError=failedWrites.size>0;announcePersistence();return ok;}
function markPersistencePending(key){if(pendingWrites.has(key))return;pendingWrites.add(key);announcePersistence();}
function productSnapshot(){return {progress:getLearningProgress(),lessons:lessons.map(l=>({id:l.id,title:l.title,...experienceLessonStatus(l.id)})),persistence:persistenceSnapshot(),route:path,activeExam:!!P.draft,attempts:P.attempts.length,achievements:Object.keys(learningAwards.earned)};}
function openCompletionPanel(id,previous){const l=lessons.find(l=>l.id===id),progress=getLearningProgress();if(!l||!progress.completedIds.includes(id))return;const all=progress.completed===progress.total,next=lessons.find(l=>!progress.completedIds.includes(l.id));dialog(all?'أنجزتها! أكملت المراجعة كاملة':'أحسنت، أكملت الوحدة',all?'اختبر ما تعلّمته عندما تكون مستعدًا.':l.title,'<section class="px-completion-panel '+(all?'px-course-complete':'')+'" aria-label="تقدّمك بعد الإكمال"><div class="px-completion-emblem" aria-hidden="true"></div><div class="px-completion-progress" data-from="'+previous.percentage+'" data-to="'+progress.percentage+'"><strong>'+progress.completed+' من '+progress.total+' وحدات مكتملة</strong><bdi class="px-animated-percentage" aria-hidden="true">'+progress.percentage+'%</bdi><div class="px-course-track" role="progressbar" aria-label="الوحدات المكتملة" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+progress.percentage+'"><span style="width:'+progress.percentage+'%"></span></div></div><p class="px-completion-save">'+(persistenceSnapshot().state==='saved'?'تقدّمك محفوظ على هذا الجهاز.':'اكتملت الوحدة في هذه الجلسة. تحقّق من حالة الحفظ أدناه.')+'</p><div class="actions">'+link(next?'/learn/'+next.id+'/':'/mock-exam/',next?'الانتقال للوحدة التالية':'ابدأ الاختبار التجريبي','button px-completion-next')+button('close-dialog','متابعة المراجعة','','button secondary')+'</div></section>');document.getElementById('dialog').classList.add('px-completion-dialog');}

function load(){try{const rawProgress=localStorage.getItem(KEY),p=JSON.parse(rawProgress||'null');if(!p||p.version!==1||!Array.isArray(p.completed)||!Array.isArray(p.practice)||!Array.isArray(p.attempts)||typeof p.currentLesson!=='string'){protectedStoredProgress=!!rawProgress;return fresh();}p.completed=p.completed.filter(x=>lessons.some(l=>l.id===x));p.practice=p.practice.filter(a=>a&&typeof a.questionId==='string'&&typeof a.answer==='string'&&typeof a.correct==='boolean');p.attempts=p.attempts.filter(a=>a&&a.answers&&typeof a.answers==='object'&&Array.isArray(a.questionIds)&&a.questionIds.every(id=>mockQuestions.some(q=>q.id===id))&&typeof a.id==='string');if(p.draft&&(!p.draft.answers||!Array.isArray(p.draft.flags)||!Array.isArray(p.draft.questionIds)||!p.draft.questionIds.length||!p.draft.questionIds.every(id=>mockQuestions.some(q=>q.id===id))||!Number.isInteger(p.draft.index)||p.draft.index<0||p.draft.index>=p.draft.questionIds.length))p.draft=null;return p;}catch{storageError=true;protectedStoredProgress=true;return fresh();}}
function save(){try{writeVerified(KEY,JSON.stringify(P));}catch{storageError=true;}$('#storage-alert').hidden=!storageError;}
function record(id,answer,correct){P.practice.push({questionId:id,answer:String(answer),correct,at:new Date().toISOString()});save();}
// 05. NAVIGATION
function readPath(){let value=location.hash.startsWith('#/')?location.hash.slice(1):'/';if(value.split('?')[0].replace(/\/$/,'')==='/learn/functions'&&new URLSearchParams(value.split('?')[1]||'').get('focus')==='loops'){value='/learn/loops/?focus=loops';history.replaceState(null,'','#'+value);}return value;}
function navigate(to){if(readPath()===to){path=to;render();window.scrollTo({top:0,behavior:'instant'});}else location.hash=to;}
function closeMenu(focus=false){menuOpen=false;$('#menu').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','فتح القائمة');$('#menu-toggle').textContent='☰';if(focus)$('#menu-toggle').focus();}
window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#/'))return;stopLoop();closeMenu();path=readPath();UI.review=false;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
// 06. UI RENDERING — every user-controlled value is escaped before insertion.
function syntax(line){const pattern=/(#[^\n]*|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\b(?:True|False|None)\b|\b(?:if|else|for|in|and|or|not)\b|\b(?:print|input|int|float|str|bool|list|range|len|sum|max|min|abs|round|sorted|pop|append)\b|\b\d+(?:\.\d+)?\b|(?:==|!=|<=|>=|\/\/|[+*/%=<>-]))/g;return line.split(pattern).filter(Boolean).map(t=>{let k='';if(t[0]==='#')k='comment';else if(/^['"]/.test(t))k='string';else if(/^(True|False|None)$/.test(t))k='literal';else if(/^(if|else|for|in|and|or|not)$/.test(t))k='keyword';else if(/^(print|input|int|float|str|bool|list|range|len|sum|max|min|abs|round|sorted|pop|append)$/.test(t))k='function';else if(/^\d/.test(t))k='number';else if(/^[+*/%=<>!-]/.test(t))k='operator';return k?`<span class="py-${k}">${esc(t)}</span>`:esc(t);}).join('');}
function code(text,highlight=-1){const id=clips.push(text)-1;return `<div class="code-window ed-code" dir="ltr"><div class="code-toolbar"><span aria-hidden="true"><i></i><i></i><i></i></span><button class="copy-code" data-act="copy" data-id="${id}" aria-label="نسخ كود بايثون">نسخ ⧉</button><small>PYTHON</small></div><pre><code>${text.split('\n').map((line,i)=>`<span class="code-line ${i===highlight?'highlighted':''}" ${i===highlight?'aria-current="step"':''}><span class="line-number" aria-hidden="true">${i+1}</span>${syntax(line||' ')}</span>`).join('')}</code></pre></div>`;}
function feedback(ok,text){return `<div class="feedback ${ok?'success':'error'}" role="status"><span aria-hidden="true">${ok?'✓':'↻'}</span><div><strong>${ok?'أحسنت، إجابة صحيحة':'لنراجع الفكرة معًا'}</strong><p>${text}</p></div></div>`;}
function tip(text){return `<div class="tip"><span aria-hidden="true">✦</span><div>${text}</div></div>`;}
function progress(value,label='التقدّم'){const n=Math.max(0,Math.min(100,value));return `<div class="progress-track" role="progressbar" aria-label="${esc(label)}" aria-valuenow="${Math.round(n)}" aria-valuemin="0" aria-valuemax="100"><div style="width:${n}%"></div></div>`;}
function pageHeading(label,title,description=''){return `<div class="page-heading"><span class="eyebrow">${label}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`;}
function render(keep=false){if(path!==lastRenderedPath){const params=new URLSearchParams(path.split("?")[1]||"");if(params.get("focus")==="loops")UI.focusRequested=path;if(params.has("function")){const index=funcs.findIndex(f=>f.name===params.get("function")+"()");if(index>=0){UI.function=index;UI.ran=false;}}if(path.startsWith("/exam")&&params.has("q"))UI.exam=Math.max(0,Math.min(5,Number(params.get("q"))-1||0));const id=path.split("/")[2];if(path.startsWith("/learn/")&&lessons.some(l=>l.id===id)){P.currentLesson=id;save();}lastRenderedPath=path;}const y=scrollY,active=document.activeElement,focusSelector=active?.dataset?.act?"button"+Object.entries(active.dataset).map(([k,value])=>"[data-"+k.replace(/[A-Z]/g,c=>"-"+c.toLowerCase())+'=' + JSON.stringify(value) + ']').join(""):"",bind=active?.dataset?.bind,start=active?.selectionStart,end=active?.selectionEnd,open=$$('details[open]').map(d=>d.id).filter(Boolean);clips=[];const home=path==='/';$('#site').className=`ed-site ${home?'ed-home':'ed-inner'} ${path.startsWith('/mock-exam')?'ed-assessment':''}`;let html;if(home)html=homeView();else if(/^\/learn\/?$/.test(path))html=catalogView();else if(path.startsWith('/learn/'))html=lessonView(path.split('/')[2]);else if(path.startsWith('/exam'))html=examView();else if(path.startsWith('/mock-exam'))html=mockView();else if(path.startsWith('/results'))html=resultsView();else html=homeView();$('#main').innerHTML=`<div class="ed-page ${keep?"no-enter":""}">${html}</div>`;$('#footer').hidden=!!(path.startsWith('/mock-exam')&&P.draft);$('#nav-start').href='#/learn/'+P.currentLesson+'/';$('#storage-alert').hidden=!storageError;$$('#menu a').forEach(a=>{const p=a.hash.slice(1);if(p==='/'?home:path.startsWith(p.slice(0,-1)))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});open.forEach(id=>{const d=document.getElementById(id);if(d)d.open=true;});if(keep){if(bind){const target=$(`[data-bind="${CSS.escape(bind)}"]`);if(target){target.focus({preventScroll:true});try{target.setSelectionRange(start,end);}catch{}}}else if(focusSelector){let target;try{target=$(focusSelector);}catch{}if(target&&!target.disabled)target.focus({preventScroll:true});else if(target){const panel=target.closest('.practice-question,.activity-panel');if(panel){panel.tabIndex=-1;panel.focus({preventScroll:true});}}}window.scrollTo({top:y,behavior:'instant'});}installReveals();assessmentChrome();applyRouteFocus();}
function homeView(){const last=P.attempts.at(-1),r=last?score(attemptQuestions(last),last.answers):null;return `<section class="film-hero" id="hero"><div class="film-bg" role="img" aria-label="مشهد أصلي لطبقات ورقية معمارية مستوحاة من أشرطة تقن، بضوء سينمائي هادئ"></div><svg class="film-logic" viewBox="0 0 600 300" aria-hidden="true"><path d="M30 200H180V100H350V50H540M180 200H380V260H550"/><text x="40" y="175">for idea in learning:</text><text x="70" y="205">understand(idea)</text><text x="340" y="75">if confidence:</text></svg><div class="film-copy"><span class="film-eyebrow"><i></i>مراجعة تفاعلية للامتحان النهائي</span><h1><span>تقن <bdi dir="ltr">107</bdi></span><span>المراجعة صارت تجربة.</span></h1><p>راجع أساسيات البايثون، حل أسئلة الامتحان السابق، واختبر مستواك بطريقة تفاعلية تساعدك تفهم كل فكرة.</p><div class="film-actions">${link('/learn/'+P.currentLesson+'/','ابدأ المراجعة','ed-button yellow')}<a class="ed-button secondary-flat" href="#journey">استكشف المحتوى <span aria-hidden="true">↓</span></a></div>${getLearningProgress().completed||P.practice.length?`<a class="hero-resume" href="#/learn/${P.currentLesson}/">↗ أكمل من وين وقفت</a>`:''}</div><span class="film-signature">TGN / LEARN WITH INTENTION<br>BAHRAIN · PYTHON · 107</span></section><section class="ed-promise" id="promise"><div class="ed-container"><span class="ed-label">ليش تقن 107؟</span><h2>مو مجرد مراجعة.</h2><p class="promise-words">${'تجربة تخليك تفهم قبل لا تحفظ.'.split(' ').map((w,i)=>`<span class="${i===2?'accent':''}">${w} </span>`).join('')}</p><p class="promise-description">كل فكرة مشروحة بصريًا، وكل سؤال تتحقق من حله بنفسك.</p></div></section>${journeyWorkspace()}${moduleList()}<section class="ed-principle"><div class="ed-container"><span class="ed-label">طريقة تقن</span><h2 class="reveal">الفكرة، ثم التجربة.<br><em>والثقة تجي بعدها.</em></h2><div class="ed-principle-grid"><div><h3>محتوى له هدف.</h3><p>المفاهيم اللي تحتاجها لفهم الامتحان، بدون تشتيت.</p></div><div><h3>كل نتيجة لها معنى.</h3><p>أخطاؤك تقودك مباشرة إلى المراجعة المناسبة.</p></div><div><h3>تعلّم على راحتك.</h3><p>تقدّمك محفوظ في المتصفح، بدون حساب أو مزامنة.</p></div></div></div></section><section class="ed-source ed-container"><div class="ed-source-art reveal">${image('/reference/cover.webp','غلاف مذكرة تقن 107 الأصلية — إعداد إبراهيم علي')}</div><div class="reveal"><span class="ed-label">من صفحاتك، إلى تجربتك.</span><h2>نفس الهوية.<br><em>مساحة أوسع للفهم.</em></h2><p>شعار تقن وألوان المذكرة وأسئلة الامتحان الأصلية. هنا تعيش الأفكار بالتجربة، وتظل مراجعك معك وقت ما تحتاجها.</p>${link('/exam/','تصفّح الامتحان والمراجع')}<span class="ed-source-note">إعداد: إبراهيم علي · مملكة البحرين</span></div></section><section class="ed-faq ed-container"><div><span class="ed-label">تفاصيل تستاهل تعرفها.</span><h2>قبل البداية،<br><em>خلّنا نوضّحها.</em></h2></div><div>${[['هل أحتاج معرفة مسبقة بالبايثون؟','تقدر تبدأ من الأساسيات. كل درس فيه فكرة قصيرة وتجربة وسؤال تتأكد فيه من فهمك.'],['هل الأسئلة السابقة مطابقة للمصدر؟','نعم. الأسئلة الست مبنية على الامتحان الأصلي المرفق، ومجموعها 40 درجة. المصدر يحتوي على نموذج الإجابة، لذلك ننبّهك قبل فتحه.'],['هل الاختبار التجريبي رسمي؟','لا. هو تدريب من 20 سؤالًا جديدًا بمجموع 40 درجة. الإجابات موجودة في الملف ويمكن لمن يفحص مصدره الاطلاع عليها.'],['وين ينحفظ تقدّمي؟','في هذا المتصفح وعلى هذا الجهاز فقط. حذف بيانات المتصفح أو تغيير مكان الملف قد يؤثر في استعادة التقدّم.'],['هل يعمل بدون إنترنت؟','نعم. الخط والخلفية والصور والمراجع وجميع التفاعلات مضمّنة داخل الملف. روابط التواصل الخارجية تحتاج اتصالًا.']].map(([q,a],i)=>`<details id="faq-${i}"><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div></section>`;}
function typePeek(){const t=typeExamples[UI.types];return `<div class="ed-type-peek"><div class="ed-peek-head"><span>TYPE EXPLORER</span><span>اختر قيمة</span></div><div class="ed-peek-value" dir="ltr">${esc(t.value)}</div><div class="ed-peek-types" dir="ltr">${typeExamples.map((x,i)=>button('select-type',x.type,`data-index="${i}" aria-pressed="${UI.types===i}"`,UI.types===i?'active':'')).join('')}</div><div class="ed-peek-answer" role="status"><strong>${t.label}</strong><p>${t.description}</p></div></div>`;}
function moduleList(heading=true){return curatedGallery(heading);}
function catalogView(){return `<div class="ed-catalog"><header class="ed-container ed-catalog-heading"><span class="ed-label">المرحلة 01 / الأساسيات</span><h1>أساس قوي.<br><em>حل أسهل.</em></h1><p>خمس وحدات قصيرة، وتجارب تشوف أثرها.<br>ابدأ بالترتيب، أو ارجع للفكرة اللي تحتاجها.</p></header>${moduleList(false)}</div>`;}
// SECTION-SPECIFIC PRESENTATION — same data and marking, different learning tools.
const lessonPresentation={loops:{label:'التكرار خطوة بخطوة',title:'افهم for، ثم راقب القيم.'},types:{label:'استكشف وقارن',title:'قيمة واحدة. أي نوع؟'},operations:{label:'مختبر الحساب',title:'غيّر العملية، وافهم الفرق.'},flowcharts:{label:'استوديو المخططات',title:'فكّر في المسار، قبل الكود.'},conditions:{label:'محاكي القرار',title:'قيمة تتغيّر. ومسار يتحدّد.'},functions:{label:'مختبر الدوال',title:'أداة واحدة في كل مرة.'}};
function originalStageProgress(){return originalGroups.map((g,i)=>{const ids=i===3?originalOutputs.map(q=>q.id):i===5?errorExamples.map(q=>q.id):['original-'+(i+1)];return ids.every(id=>P.practice.some(a=>a.questionId===id&&a.correct));}).filter(Boolean).length;}
function journeyWorkspace(){const originalDone=originalStageProgress(),last=P.attempts.at(-1),r=last?score(attemptQuestions(last),last.answers):null,stage=UI.stage??(getLearningProgress().completed<lessons.length?0:originalDone<6?1:2),items=[{title:'أساسيات المادة',label:'الفهم يبدأ من هنا',desc:'ست وحدات قصيرة. افهم كيف يتعامل بايثون مع القيم والعمليات والقرارات، وجرّب كل فكرة بنفسك.',objectives:['ميّز أنواع البيانات ونتائج العمليات.','ابنِ مسار الحل، وجرّب الشروط والدوال.'],href:'/learn/',action:'ادخل الأساسيات',total:lessons.length,done:getLearningProgress().completed,status:getLearningProgress().completed===lessons.length?'مكتملة':getLearningProgress().completed?'قيد التقدّم':'متاحة الآن'},{title:'حل الامتحان السابق',label:'من الفهم إلى التطبيق',desc:'ستة أسئلة أصلية بمجموع 40 درجة. جاوب أولًا، ثم راجع السبب وتتبع خطوات الحل.',objectives:['حل السؤال دون كشف الإجابة أولًا.','راجع المخرجات والتكرار وتصحيح الأخطاء.'],href:'/exam/',action:'افتح مساحة الحل',total:6,done:originalDone,status:originalDone===6?'مكتملة':P.practice.some(a=>a.questionId.startsWith('original-'))?'قيد التقدّم':'متاحة الآن'},{title:'الاختبار التجريبي',label:'اعرف مستواك وحدّد خطوتك',desc:'20 سؤالًا تدريبيًا جديدًا، ونتيجة فعلية ترشدك إلى المراجعة المناسبة.',objectives:['اختبر فهمك دون إظهار الحلول أثناء المحاولة.','ارجع إلى الدروس المرتبطة بأخطائك.'],href:'/mock-exam/',action:P.draft?'أكمل الاختبار':'ابدأ الاختبار التجريبي',total:1,done:P.attempts.length?1:0,status:P.draft?'محاولة جارية':P.attempts.length?'لديك نتائج':'متاحة الآن'}],s=items[stage];return `<section class="journey-section-v2 ed-container" id="journey"><div class="ed-section-title reveal"><div><span class="ed-label">رحلة المراجعة / خريطة واضحة</span><h2>خطوتك الآن.<br><em>واللي بعدها.</em></h2></div><p>اختر مرحلة لتعرف هدفها وتقدّمك.<br>تقدر تدخل أي مرحلة متى ما احتجتها.</p></div><div class="journey-stops" role="group" aria-label="اختر مرحلة المراجعة">${items.map((x,i)=>`<button data-act="journey-stage" data-index="${i}" class="journey-stop ${stage===i?'active':''} ${x.done===x.total?'complete':''}" aria-pressed="${stage===i}"><span class="journey-stop-number">${x.done===x.total?'✓':'0'+(i+1)}</span><strong>${x.title}</strong><small>${x.status}</small></button>`).join('')}</div><div class="journey-insight journey-insight-${stage}" aria-live="polite"><div class="journey-insight-copy"><span class="ed-label">0${stage+1} / ${s.label}</span><h3>${s.title}</h3><p>${s.desc}</p><ul>${s.objectives.map(t=>`<li>${t}</li>`).join('')}</ul><div class="journey-real-progress"><span>${stage<2?s.done+' من '+s.total+' مكتملة':P.draft?'إجابات محفوظة: '+Object.keys(P.draft.answers).length+' / '+P.draft.questionIds.length:P.attempts.length?'محاولات محفوظة: '+P.attempts.length:'لم تبدأ محاولة بعد'}</span>${progress(stage<2?s.done/s.total*100:P.draft?Object.keys(P.draft.answers).length/P.draft.questionIds.length*100:s.done*100,s.title)}</div>${link(s.href,s.action,'ed-button yellow')}</div><div class="journey-insight-visual">${stage===0?typePeek():stage===1?`<div class="ed-practice-peek"><div><span>نحلّها خطوة بخطوة.</span><span dir="ltr">PRACTICE / 06</span></div>${code(loopCode)}<p><span>i</span><span>x</span><span>y</span><strong>جدول قيم، مو تخمين.</strong></p></div>`:`<div class="ed-result-peek"><span class="ed-label">${r?'آخر نتيجتك الفعلية':'الجاهزية تُبنى بالمحاولة'}</span><div><b>${r?r.earned:'—'}</b><span>/ ${r?r.total:40}</span></div><p>${r?r.percent+'% · افتح النتائج لتفهم خطوتك القادمة.':'تدريب، ثم نتيجة، ثم خطة مراجعة.'}</p>${link(r?'/results/':'/mock-exam/',r?'افتح نتيجتك':'تعرّف على الاختبار')}</div>`}</div></div></section>`;}
function recommendedModule(){const a=selectedAttempt();if(a){const weak=weakTopics(a);if(weak.length)return {id:lessonFor[weak[0][0]],reason:'مقترح من نتيجتك: '+topicLabels[weak[0][0]]};}const next=lessons.find(l=>!P.completed.includes(l.id));return {id:next?.id||P.currentLesson,reason:next?'خطوتك التالية في الأساسيات':'متاح للمراجعة من جديد'};}
function galleryPreview(id){if(id==='types')return `<div class="gallery-types" dir="ltr"><span><code>20</code><b>int</b></span><span><code>"20"</code><b>str</b></span><small>نفس الرمز، نوع مختلف.</small></div>`;if(id==='operations')return `<div class="gallery-arithmetic" dir="ltr"><code>9 / 2 <b>4.5</b></code><code>9 // 2 <b>4</b></code></div>`;if(id==='flowcharts')return `<div class="gallery-flow" dir="ltr">${flowShape('start','بداية')}<span aria-hidden="true">→</span>${flowShape('decision','sm < 100')}</div>`;if(id==='loops')return `<div class="gallery-function" dir="ltr"><code>for i in range(5, 10, 2)</code><span>↓</span><code>5 · 7 · 9</code></div>`;if(id==='conditions')return `<div class="gallery-condition" dir="ltr"><code>100 &lt; 100</code><span>False ↗</span></div>`;return `<div class="gallery-function" dir="ltr"><code>sorted([8, 7])</code><span>↓</span><code>[7, 8]</code></div>`;}
function curatedGallery(heading=true){const rec=recommendedModule(),visible=lessons.filter(l=>UI.filter==='all'||UI.filter==='done'&&P.completed.includes(l.id)||UI.filter==='todo'&&!P.completed.includes(l.id)),featured=visible.find(l=>l.id===rec.id)||visible[0],ordered=featured?[featured,...visible.filter(l=>l.id!==featured.id)]:[];return `<section class="curated-catalog" id="modules"><div class="ed-container">${heading?`<div class="ed-section-title"><div><span class="ed-label">اختر فكرتك القادمة</span><h2>موضوع واحد.<br><em>وتركيز أوضح.</em></h2></div><p>افتح الدرس المناسب لك.<br>كل موضوع له طريقة مختلفة للفهم.</p></div>`:''}<div class="ed-module-filter"><span>${getLearningProgress().completed} / ${lessons.length} دروس مكتملة</span><label>اعرض<select data-bind="filter" aria-label="تصفية الدروس"><option value="all" ${UI.filter==='all'?'selected':''}>كل الدروس</option><option value="todo" ${UI.filter==='todo'?'selected':''}>لم تكتمل بعد</option><option value="done" ${UI.filter==='done'?'selected':''}>مكتملة</option></select></label></div><div class="catalog-gallery">${ordered.map((l,i)=>`<a href="#/learn/${l.id}/" class="catalog-tile catalog-${l.id} ${i===0?'featured':i<3?'supporting':'compact'}"><div class="catalog-tile-meta"><span>${i===0&&l.id===rec.id?esc(rec.reason):'0'+(lessons.findIndex(x=>x.id===l.id)+1)+' / '+l.en}</span><span>${P.completed.includes(l.id)?'✓ مكتمل':l.minutes+' دقائق'}</span></div>${galleryPreview(l.id)}<div class="catalog-tile-copy"><h3>${l.title}</h3><p>${l.description}</p><span class="catalog-enter">افتح الدرس ${arrow}</span></div></a>`).join('')}</div>${!visible.length?`<div class="ed-empty-filter"><h3>أول درس ينتظرك.</h3><p>ما عندك دروس مكتملة بعد. ابدأ بفكرة واحدة.</p>${button('all-lessons','اعرض كل الدروس','','ed-text-link')}</div>`:''}</div></section>`;}
function typeComparisonWorkspace(){const t=typeExamples[UI.types],quiz=typeExamples[UI.typeQuiz],examExamples=['b = int(input("Mark= "))','e = b / 2','c = input("Name: ")','d = a[2]','a = ["Test1", 20, True]'];return `<div class="type-workspace"><div class="type-grid type-selector" role="group" aria-label="اختر نوعًا للاستكشاف">${typeExamples.map((x,i)=>`<button data-act="select-type" data-index="${i}" class="type-card ${UI.types===i?'selected':''}" aria-pressed="${UI.types===i}"><code dir="ltr">${esc(x.value)}</code><span><b dir="ltr">${x.type}</b><small>${x.label}</small></span><span aria-hidden="true">${UI.types===i?'✓':'↗'}</span></button>`).join('')}</div><div class="type-detail"><span class="ed-label">القيمة والنوع</span><div class="type-detail-value" dir="ltr">${esc(t.value)}<small>${t.type}</small></div><h3>${t.label}</h3><p>${t.description}</p><div class="type-exam-context"><small>صلة بفكرة الامتحان</small>${code(examExamples[UI.types])}<p>${['int() تحوّل الإدخال العددي المناسب إلى عدد صحيح.','القسمة / تعيد float حتى لو كان الناتج مثل 4.0.','input() تعيد نصًا، حتى عند إدخال أرقام.','العنصر الثالث في القائمة الأصلية هو True، من النوع bool.','القائمة قد تحتوي على عناصر من أنواع مختلفة.'][UI.types]}</p></div></div></div><details class="type-comparison" id="type-comparison"><summary>قارن الأنواع جنبًا إلى جنب <span aria-hidden="true">+</span></summary><div>${typeExamples.map(x=>`<span><code dir="ltr">${esc(x.value)}</code><bdi>${x.type}</bdi><small>${x.label}</small></span>`).join('')}</div></details><div class="mini-exercise"><div class="mini-exercise-heading"><span class="ed-label">جرّب تمييز القيمة</span><h3>ما نوع البيانات؟</h3></div><code class="big-code" dir="ltr">${esc(quiz.value)}</code><div class="chips" dir="ltr">${typeExamples.map(x=>button('mini-type',x.type,`data-type="${x.type}" aria-pressed="${UI.miniType===x.type}"`,UI.miniType===x.type?'chip selected':'chip')).join('')}</div>${UI.miniType?feedback(UI.miniType===quiz.type,`${quiz.description} النوع الصحيح: <bdi>${quiz.type}</bdi>.`):''}${button('next-type','قيمة جديدة ←','','text-button')}</div>`;}
function operationComparison(a,b){return `<div class="division-comparison" aria-label="قارن أنواع القسمة" dir="ltr">${[['/','قسمة','float'],['//','قسمة أرضية','عدد أرضي'],['%','باقي القسمة','الباقي']].map(([op,label])=>{const r=String(a).trim()&&String(b).trim()?operate(Number(a),Number(b),op):'—',value=typeof r==='number'&&op==='/'&&Number.isInteger(r)?r+'.0':String(r);return `<div data-compare-op="${op}" class="${UI.operator===op?'active':''}"><span>${label}</span><code>${esc(a||'?')} ${op} ${esc(b||'?')}</code><strong>${esc(value)}</strong><small>${label==='قسمة'?'ناتج عشري':op==='//'?'تقريب نحو الأسفل':'ما يتبقّى'}</small></div>`;}).join('')}</div>`;}
function calculationWorkspace(){const a=v('opA','9'),b=v('opB','2'),result=String(a).trim()&&String(b).trim()?operate(Number(a),Number(b),UI.operator):'أدخل عددين صالحين',shown=typeof result==='number'&&UI.operator==='/'&&Number.isInteger(result)?result+'.0':String(result);return `<div class="calculation-workspace"><div class="operation-controls" dir="ltr"><label>العدد الأول${input('opA','العدد الأول',a,'number')}</label><label>العملية<select data-bind="operator" aria-label="العملية">${['+','-','*','/','//','%'].map(o=>`<option ${UI.operator===o?'selected':''}>${o}</option>`).join('')}</select></label><label>العدد الثاني${input('opB','العدد الثاني',b,'number')}</label></div><div class="calculation" dir="ltr"><span>${esc(a||'?')} ${esc(UI.operator)} ${esc(b||'?')}</span><span>=</span><strong aria-live="polite">${esc(shown)}</strong></div><p class="calculation-explanation">${UI.operator==='/'?'القسمة / تحتفظ بالجزء العشري.':UI.operator==='//'?'القسمة الأرضية تقرّب إلى الأسفل، وليس نحو الصفر.':UI.operator==='%'?'هذه هي القيمة المتبقية بعد القسمة.':'غيّر العددين ولاحظ أثر العملية.'}</p><div id="division-comparison">${operationComparison(a,b)}</div>${tip('جرّب -9 مع 2: القسمة الأرضية -5، والباقي 1. إذا كان المقسوم عليه صفرًا، نظهر تنبيهًا بدل نتيجة غير صحيحة.')}<details id="operator-reference"><summary>مرجع العمليات الست</summary><div class="operator-grid">${[['+','جمع'],['-','طرح'],['*','ضرب'],['/','قسمة'],['//','قسمة أرضية'],['%','باقي القسمة']].map(([op,label])=>`<button class="operator-card ${UI.operator===op?'selected':''}" data-act="set-operator" data-op="${op}" aria-pressed="${UI.operator===op}"><code>${op}</code><span>${label}</span></button>`).join('')}</div></details></div>`;}
function diagramStudio(){const ok=UI.slots.every((x,i)=>x===blocks[i][0]),selected=shapeData.find(x=>x[0]===UI.shape),uses={start:'نبدأ قراءة الخطوات أو ننهي التنفيذ.',io:'مثل قراءة الاسم أو طباعة المجموع.',process:'مثل sm = sum(Ltest).',decision:'مثل sm < 100: نتيجتان، Yes أو No.',arrow:'ننتقل إلى الخطوة التالية حسب اتجاه السهم.'};return `<div class="diagram-studio"><div class="shape-explorer studio-palette" role="group" aria-label="اختر شكلًا">${shapeData.map(([id,label])=>`<button class="shape-button ${UI.shape===id?'selected':''}" data-act="select-shape" data-id="${id}" aria-pressed="${UI.shape===id}">${flowShape(id,'').replace('role="img" aria-label=""','aria-hidden="true"')}<span>${label}</span></button>`).join('')}</div><div class="studio-canvas"><span class="ed-label">استكشف وظيفة الشكل</span><div class="studio-shape">${flowShape(UI.shape,selected[1],true)}</div><h3>${selected[1]}</h3><p class="shape-description" aria-live="polite">${selected[2]}</p><small>${uses[UI.shape]}</small></div></div><div class="activity-divider"></div><div class="builder-heading"><div><span class="ed-label">من الشكل إلى المسار</span><h3>ركّب مخططك.</h3></div><p>اسحب كتلة، أو اخترها ثم اضغط على الخانة.</p></div><div class="chips builder-toolbelt">${blocks.map(([id,label])=>`<button draggable="true" data-block="${id}" data-act="select-block" class="chip ${UI.block===id?'selected':''}" aria-pressed="${UI.block===id}">${esc(label)}</button>`).join('')}</div><div class="builder-canvas"><svg class="builder-connectors" viewBox="0 0 600 610" preserveAspectRatio="none" aria-hidden="true"><path d="M220 60V550M220 300H510V540H220"/><text x="250" y="340">Yes</text><text x="440" y="288">No</text></svg><div class="flow-builder">${UI.slots.map((x,i)=>`<div class="flow-slot-wrap"><button class="flow-slot ${UI.builderChecked?(x===blocks[i][0]?'valid':'invalid'):''}" data-act="place-block" data-slot="${i}" aria-label="الخانة ${i+1}: ${esc(blocks.find(b=>b[0]===x)?.[1]||'فارغة')}">${x?flowShape(x,blocks.find(b=>b[0]===x)?.[1]||''):'<span>+ الخطوة '+(i+1)+'</span>'}</button></div>`).join('')}</div><div class="builder-alternative">${flowShape('io','نتيجة بديلة')}<small>المسار الآخر يعود إلى النهاية.</small></div></div><div class="actions">${button('check-builder','تحقّق من الترتيب ✓',UI.slots.some(x=>!x)?'disabled':'')}${button('reset-builder','إعادة المحاولة ↺','','button secondary')}</div>${UI.builderChecked?feedback(ok,'الترتيب الصحيح: بداية ← حساب المجموع ← قرار ← عرض النتيجة ← نهاية. للقرار مسارا Yes وNo، ويعودان إلى النهاية.'):''}`;}
function decisionCanvas(sm,op){const yes=compare(sm,op);return `<svg class="decision-map" viewBox="0 0 640 260" role="img" aria-label="${esc(sm+' '+op+' 100')}: ${yes?'True، مسار Yes':'False، مسار No'}"><path class="decision-line" d="M320 16V45M245 92H125V177M395 92H515V177"/><path class="decision-active" d="${yes?'M320 16V45M245 92H125V177':'M320 16V45M395 92H515V177'}"/><polygon points="320,42 400,92 320,142 240,92"/><text class="decision-condition" x="320" y="98" text-anchor="middle">sm ${esc(op)} 100</text><text x="130" y="152" text-anchor="middle">Yes · True</text><text x="510" y="152" text-anchor="middle">No · False</text><g class="branch ${yes?'selected':''}"><rect x="35" y="178" width="180" height="61" rx="12"/><text x="125" y="215" text-anchor="middle">نفّذ كتلة if</text></g><g class="branch ${!yes?'selected':''}"><rect x="425" y="178" width="180" height="61" rx="12"/><text x="515" y="215" text-anchor="middle">نفّذ كتلة else</text></g></svg>`;}
function decisionWorkspace(){const yes=compare(UI.sm,UI.comparison);return `<div class="decision-workspace"><div class="decision-controls"><div class="range-header"><label for="sum-range">قيمة <bdi>sm</bdi></label><output for="sum-range">${UI.sm}</output></div>${input('sm','قيمة sm',UI.sm,'range','id="sum-range" min="0" max="150"')}<div class="chips">${[75,100,120].map(n=>button('set-sum','<bdi>sm = '+n+'</bdi>',`data-value="${n}" aria-pressed="${UI.sm===n}"`,UI.sm===n?'chip selected':'chip')).join('')}</div><details id="comparison-tools"><summary>غيّر عامل المقارنة <code dir="ltr">${esc(UI.comparison)}</code></summary><div class="comparison-select" role="group" aria-label="عامل المقارنة" dir="ltr">${['>','<','==','!=','>=','<='].map(op=>button('comparison',esc(op),`data-op="${op}" aria-pressed="${UI.comparison===op}"`,UI.comparison===op?'chip selected':'chip')).join('')}</div></details></div><div class="decision-execution"><div class="live-flow">${decisionCanvas(UI.sm,UI.comparison)}</div><div id="decision-status" class="feedback success" role="status"><div><strong dir="ltr">${UI.sm} ${esc(UI.comparison)} 100 → ${yes?'True':'False'}</strong><p>${UI.sm===100&&UI.comparison==='<'?'100 ليست أصغر من 100، ولذلك نتبع مسار No.':'الشرط '+(yes?'متحقق، فننفّذ if.':'غير متحقق، فننفّذ else.')}</p></div></div><div id="condition-code">${code('if sm '+UI.comparison+' 100:\n    print("Yes")\nelse:\n    print("No")',yes?1:3)}</div></div></div>`;}
function functionVisual(f){const list=(items,highlight=null)=>`<div class="fn-list" dir="ltr">${items.map((n,i)=>`<span class="${n===highlight?'highlight':''}" style="--order:${i}">${esc(n)}</span>`).join('')}</div>`;if(f.name==='max()'||f.name==='min()')return `<div class="fn-visual"><small>${f.name==='max()'?'أكبر قيمة تُختار.':'أصغر قيمة تُختار.'}</small>${list([3,7,1],Number(f.result))}</div>`;if(f.name==='pop()')return `<div class="fn-visual"><small>حذف الفهرس 0، مع إعادة العنصر المحذوف.</small><div class="native-list"><span class="removed">5</span><span>8</span><span>7</span></div><p>القائمة الآن <code dir="ltr">[8, 7]</code>، والقيمة المعادة <bdi>5</bdi>.</p></div>`;if(f.name==='sorted()')return `<div class="fn-visual"><small>الأصل يبقى كما هو.</small>${list([8,7])}<span class="fn-arrow">↓ قائمة جديدة مرتّبة</span><div class="fn-list fn-sorted" dir="ltr"><span style="--shift:64px">7</span><span style="--shift:-64px">8</span></div></div>`;if(f.name==='range()')return `<div class="fn-visual"><small>ابدأ من 5، زِد 2، وتوقّف قبل 10.</small><div class="fn-sequence" dir="ltr"><span>5</span>→<span>7</span>→<span>9</span><small>10 مستبعدة</small></div></div>`;if(f.name==='sum()')return `<div class="fn-visual"><small>نجمع العناصر بالترتيب.</small><div class="fn-sequence" dir="ltr"><span>10</span>→<span>30</span>→<span>60</span></div><p><bdi>10 + 20 + 30 = 60</bdi></p></div>`;if(f.name==='len()')return `<div class="fn-visual"><small>كل حرف يُحسب مرة.</small><div class="fn-characters" dir="ltr">${['A','l','i'].map((x,i)=>`<span>${x}<small>${i+1}</small></span>`).join('')}</div></div>`;if(f.name==='append()')return `<div class="fn-visual"><small>عنصر جديد في نهاية القائمة.</small><div class="fn-sequence" dir="ltr"><code>[]</code>→<span>"Ali"</span></div></div>`;if(f.name==='abs()')return `<div class="fn-visual"><small>المسافة عن الصفر دون الإشارة السالبة.</small><div class="fn-sequence" dir="ltr"><span>-28</span>→<span>28</span></div></div>`;if(f.name==='round()')return `<div class="fn-visual"><small>العدد الصحيح الأقرب في هذا المثال.</small><div class="fn-sequence" dir="ltr"><span>27.6</span>→<span>28</span></div></div>`;if(f.name==='int()')return `<div class="fn-visual"><small>نفس القيمة، من نص إلى عدد صحيح.</small><div class="fn-sequence" dir="ltr"><span>"20"<small>str</small></span>→<span>20<small>int</small></span></div></div>`;if(f.name==='input()')return `<div class="fn-visual"><small>إدخال المستخدم نص، مهما بدا رقميًا.</small><div class="fn-sequence" dir="ltr"><span>Ali</span>→<span>str</span></div></div>`;return `<div class="fn-visual"><small>تظهر القيمة على الشاشة.</small><div class="fn-console" dir="ltr">Hello<span aria-hidden="true">▏</span></div></div>`;}
function rangeOverview(){return `<div class="ft-range-overview" role="group" aria-label="مثال range: البداية 5، والنهاية 10 غير مشمولة، والخطوة 2">
 <div class="ft-range-signature" dir="ltr"><code>range(</code><span class="ft-range-argument"><code>5,</code><small dir="rtl">البداية</small></span><span class="ft-range-argument"><code>10,</code><small dir="rtl">النهاية</small></span><span class="ft-range-argument"><code>2</code><small dir="rtl">الخطوة</small></span><code>)</code></div>
 <p>تبدأ من 5، وتزيد 2 كل مرة. <strong>10 غير مشمولة.</strong></p><span class="ft-range-values">القيم الناتجة <bdi dir="ltr">5 → 7 → 9</bdi></span>
</div>`;}
function isRangeLesson(){return path.startsWith('/learn/functions/')&&funcs[UI.function]?.name==='range()';}
function rangeFunctionLaboratory(f,q){
 const passed=!!UI.checked[q.id]&&normalize(UI.answers[q.id]||'')===normalize(q.answer),states=[v('range.example.done')==='1',v('range.values.done')==='1'||v('range.trace.done')==='1',passed],complete=states.filter(Boolean).length;
 const valueIndex=Math.max(0,Math.min(2,Number(v('range.value.index','0'))||0)),values=[5,7,9];
 const quickQuestion={...q,prompt:'أي قائمة تنتج عن هذا المثال؟',options:[f.result,'[5, 7, 9, 10]','[5, 6, 7, 8, 9]'],explanation:'نبدأ من 5 ونضيف 2: 5 ثم 7 ثم 9. نتوقّف قبل 10 لأن النهاية غير مشمولة.'};
 const stages=[['range-understand','الفكرة'],['range-loop','التجربة'],['range-question','السؤال']];
 return `<div class="function-lab ft-range-view"><aside class="function-grid lab-selector" aria-label="اختر دالة">${funcs.map((x,i)=>button('select-function',`<code dir="ltr">${x.name}</code>`,`data-index="${i}" aria-pressed="${UI.function===i}"`,UI.function===i?'function-chip selected':'function-chip')).join('')}</aside><div class="lab-bench">
  <section class="range-function-lesson" aria-labelledby="range-function-title"><header class="range-function-heading"><span>شرح الدالة المحدّدة</span><h3 id="range-function-title"><code dir="ltr">range()</code></h3><p>تُجهّز سلسلة أعداد ببداية ونهاية وخطوة. جرّب قيمها، ثم تأكّد من فهمك.</p></header>
   <div class="range-learning-progress"><div><strong>تقدّمك في مسار <bdi dir="ltr">range()</bdi></strong><span><bdi>${complete}</bdi> من 3 أنشطة مكتملة</span></div><div role="progressbar" aria-label="تقدّم أنشطة range" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${complete}"><span style="width:${complete/3*100}%"></span></div></div>
   <nav class="range-learning-stages" aria-label="خطوات تعلّم range">${stages.map(([id,title],index)=>`<a href="#${id}" class="${states[index]?'is-complete':''}" aria-label="الخطوة ${index+1}: ${title}، ${states[index]?'مكتملة':'متاحة'}"><span class="range-stage-number" aria-hidden="true">${index+1}</span><span>${title}<small>${states[index]?'مكتمل':'متاح'}</small></span></a>`).join('')}</nav>
   <section class="range-learning-stage" id="range-understand" tabindex="-1"><h4><span aria-hidden="true">01</span> افهم دالة <bdi dir="ltr">range()</bdi></h4>${rangeOverview()}${code(f.code)}<p class="range-list-note">نستخدم <code dir="ltr">list()</code> هنا لعرض القيم كقائمة.</p>${button('run-function',UI.ran?'عُرضت القيم':v('range.example.done')==='1'?'اعرض القيم مجدّدًا':'اعرض القيم',UI.ran?'disabled':'')}${UI.ran?`<div class="function-output range-example-output" role="status"><span>القيم الناتجة</span><strong dir="ltr">${esc(f.result)}</strong></div>`:''}</section>
   <section class="range-learning-stage" id="range-loop" tabindex="-1"><h4><span aria-hidden="true">02</span> جرّب القيم</h4><p class="range-loop-intro">انتقل بين قيم السلسلة، ولاحظ الزيادة بمقدار الخطوة.</p>
    <div class="range-values-demo"><div class="range-value-buttons" role="group" aria-label="قيم range">${values.map((value,index)=>button('range-value',String(value),`data-index="${index}" aria-pressed="${index===valueIndex}" aria-label="القيمة ${index+1}: ${value}"`,index===valueIndex?'range-value selected':'range-value')).join('')}</div><div class="range-current-value" role="status" aria-live="polite"><span>القيمة ${valueIndex+1} من 3</span><strong dir="ltr">${values[valueIndex]}</strong><code dir="ltr">${valueIndex===0?'start = 5':values[valueIndex-1]+' + 2 = '+values[valueIndex]}</code></div><div class="range-value-controls">${button('range-prev-value','السابق',valueIndex===0?'disabled':'','button secondary')}${button('range-next-value','التالي',valueIndex===2?'disabled':'','button')}</div><p class="range-values-end">النهاية 10 غير مشمولة؛ آخر قيمة هنا هي 9.</p></div><a class="text-button" href="#/learn/loops/">تعلّم استخدام القيم في درس التكرار ←</a>
   </section>
   <section class="range-learning-stage" id="range-question" tabindex="-1"><h4><span aria-hidden="true">03</span> سؤال قصير عن <bdi dir="ltr">range()</bdi></h4>${question(quickQuestion)}</section>
  </section>
 </div></div>`;
}

function functionLaboratory(){const f=funcs[UI.function],q=findQuestion('function-'+UI.function);if(f.name==='range()')return rangeFunctionLaboratory(f,q);return `<div class="function-lab"><aside class="function-grid lab-selector" aria-label="اختر دالة">${funcs.map((x,i)=>button('select-function',`<code dir="ltr">${x.name}</code>`,`data-index="${i}" aria-pressed="${UI.function===i}"`,UI.function===i?'function-chip selected':'function-chip')).join('')}</aside><div class="lab-bench"><div class="function-detail"><span class="ed-label">مثال واحد، وأثر واضح.</span><h3 dir="ltr">${f.name}</h3><p>${f.desc}</p>${code(f.code)}${button('run-function',UI.ran?'تم التنفيذ':'جرّب المثال',UI.ran?'disabled':'')}${UI.ran?`<div class="function-output" role="status"><span>الناتج</span><strong dir="ltr">${esc(f.result)}</strong></div>${functionVisual(f)}`:'<p class="lab-hint">توقّع النتيجة أولًا، ثم جرّب المثال.</p>'}</div><details class="function-practice" id="function-practice"><summary>اختبر فهمك لهذه الدالة <span>↗</span></summary><div class="mini-exercise">${question(q)}</div></details></div></div>`;}
function executionTimeline(showRangeOverview=true){
 const s=loopStates[UI.step],before=UI.step?loopStates[UI.step-1]:{i:'—',x:'—',y:'—',z:'—'},last=loopStates.length-1;
 const traceId=path.startsWith('/exam')?'exam-loop-trace':'lesson-loop-trace',iteration=UI.step>=2&&UI.step<=10?Math.floor((UI.step-2)/3)+1:null;
 const phase=iteration?'الدورة '+iteration+' من 3':UI.step<2?'تهيئة المتغيّرات':'حساب النتيجة وعرضها';
 const titles=['إسناد قيمة البداية إلى x','تهيئة y بالصفر','اختيار قيمة التكرار i','طرح i من x','إضافة 2 إلى y','جمع x وy في z','طباعة قيمة z'];
 const expressions=['x = 50','y = 0','i = '+s.i,'x = '+before.x+' − '+s.i+' = '+s.x,'y = '+before.y+' + 2 = '+s.y,'z = '+s.x+' + '+s.y+' = '+s.z,'print(z) → '+s.z];
 const hints=['بدأنا بقيمة 50، ولم تُهيَّأ بقية المتغيّرات بعد.','أصبحت y جاهزة لتجميع الزيادة في كل دورة.','القيم هي 5 ثم 7 ثم 9. النهاية 10 غير مشمولة.','تغيّرت x فقط؛ بقيت القيم الأخرى كما هي.','تغيّرت y فقط؛ نضيف إليها 2 في كل دورة.','انتهت الدورات الثلاث. نحسب z قبل طباعتها.','الآن يظهر الناتج في المخرجات. لم تتغيّر قيم المتغيّرات.'];
 const descriptions={i:'قيمة التكرار',x:'نطرح منها i',y:'نزيدها بمقدار 2',z:'مجموع x وy'};
 const controlIcon=kind=>'<svg class="ft-control-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+(kind==='play'?'<path d="m8 5 11 7-11 7Z"/>':kind==='pause'?'<path d="M8 5v14M16 5v14"/>':kind==='reset'?'<path d="M4 10a8 8 0 1 1 1 8M4 4v6h6"/>':'<path d="M4 12h16m-6-6 6 6-6 6"/>')+'</svg>';
 return `<div class="loop-visualizer ft-trace" data-trace-step="${UI.step}" data-trace-playing="${UI.playing}">
  ${showRangeOverview?rangeOverview():''}
  <div class="ft-trace-status" id="${traceId}-step"><span class="ft-step-count">الخطوة <bdi>${UI.step+1}</bdi><span>من ${loopStates.length}</span></span><span class="ft-phase">${phase}</span></div>
  <div class="ft-step-progress" role="progressbar" aria-label="خطوات التنفيذ" aria-valuemin="1" aria-valuemax="${loopStates.length}" aria-valuenow="${UI.step+1}"><span style="width:${(UI.step+1)/loopStates.length*100}%"></span></div>
  <div class="trace-workspace">
   <section class="trace-code" aria-label="الكود والسطر الذي نُفّذ"><div class="ft-panel-heading"><h3>الكود</h3><span>السطر <bdi>${s.line+1}</bdi> · نُفّذ الآن</span></div>${code(loopCode,s.line)}
    <div class="ft-output ${UI.step===last?'has-output':''}" aria-label="المخرجات المطبوعة"><span>المخرجات</span><strong dir="ltr">${UI.step===last?esc(s.z):'—'}</strong><small>${UI.step===last?'ناتج print(z)':'لم يُطبع شيء بعد'}</small></div>
   </section>
   <section class="trace-inspector" id="${traceId}-state" aria-label="قيم المتغيّرات بعد الخطوة الحالية"><div class="ft-panel-heading"><h3>قيم المتغيّرات</h3><span>بعد تنفيذ السطر</span></div>
    <div class="variable-grid" dir="ltr">${['i','x','y','z'].map(k=>{const changed=s[k]!==before[k],assigned=s[k]!=='—';return `<div class="ft-variable ${changed?'variable-changed':''} ${assigned?'':'is-unassigned'}" aria-label="${k}: ${assigned?esc(s[k]):'لم تُسنَد بعد'}${changed?'، تغيّرت في هذه الخطوة':''}"><div class="ft-variable-top"><code>${k}</code><span class="ft-variable-status">${changed?'تغيّرت':assigned?'ثابتة':'لم تُسنَد'}</span></div><strong>${esc(s[k])}</strong><span class="ft-variable-description" dir="rtl">${descriptions[k]}</span><small dir="rtl">${changed?(before[k]==='—'?'قيمة جديدة':'كانت <bdi dir="ltr">'+esc(before[k])+'</bdi>'):assigned?'لم تتغيّر':'لم يصلها التنفيذ بعد'}</small></div>`;}).join('')}</div>
    <div class="ft-step-explanation"><span class="ft-explanation-label">ماذا حدث؟</span><h4>${titles[s.line]}</h4><code class="ft-step-equation" dir="ltr">${esc(expressions[s.line])}</code><p class="trace-note" role="status" aria-live="${UI.playing?'off':'polite'}" aria-atomic="true">${hints[s.line]}</p></div>
   </section>
  </div>
  <div class="ft-trace-controls" role="group" aria-label="التحكّم في التتبّع">
   ${button('loop-prev',controlIcon('previous')+'<span>السابق</span>',`${UI.step===0?'disabled':''} aria-label="الخطوة السابقة" aria-controls="${traceId}-state"`,'button secondary ft-previous')}
   ${button('loop-next','التالي',`${UI.step===last?'disabled':''} aria-label="الخطوة التالية" aria-controls="${traceId}-state"`,'button ft-next')}
   ${button('loop-play',controlIcon(UI.playing?'pause':'play')+'<span>'+(UI.playing?'إيقاف':'تشغيل')+'</span>',`aria-pressed="${UI.playing}" aria-label="${UI.playing?'إيقاف التتبّع مؤقتًا':UI.step===last?'تشغيل التتبّع من البداية':'تشغيل التتبّع تلقائيًا'}" aria-controls="${traceId}-state"`,'button secondary ft-play')}
   ${button('loop-reset',controlIcon('reset')+'<span>إعادة</span>',`${UI.step===0&&!UI.playing?'disabled':''} aria-label="إعادة التتبّع من البداية" aria-controls="${traceId}-state"`,'text-button ft-reset')}
  </div>
  <div class="execution-timeline"><div><strong>اختر خطوة</strong><small>المحدّدة هي الخطوة المعروضة الآن</small></div><div role="group" aria-label="خطوات التنفيذ">${loopStates.map((state,index)=>button('loop-jump',String(index+1),`data-index="${index}" aria-label="الخطوة ${index+1}: ${titles[state.line]}" aria-pressed="${index===UI.step}" tabindex="${index===UI.step?'0':'-1'}" ${index===UI.step?'aria-current="step"':''}`,index===UI.step?'active':index<UI.step?'past':'')).join('')}</div></div>
 </div>`;
}
// 07. LEARNING INTERACTIONS — deterministic Python models, never arbitrary execution.
function operate(a,b,op){if(!Number.isFinite(a)||!Number.isFinite(b))return 'أدخل عددين صالحين';if(b===0&&['/','//','%'].includes(op))return 'لا يمكن القسمة على صفر';switch(op){case '+':return a+b;case '-':return a-b;case '*':return a*b;case '/':return a/b;case '//':return Math.floor(a/b);case '%':return a-Math.floor(a/b)*b;default:return 'اختر عملية';}}
function flowShape(kind,label,active=false){const shape=kind==='start'||kind==='end'?'<rect x="16" y="17" width="148" height="56" rx="28"/>':kind==='decision'?'<polygon points="90,5 175,45 90,85 5,45"/>':kind==='io'?'<polygon points="30,17 173,17 150,73 7,73"/>':kind==='arrow'?'<path d="M25 45H150M130 25L150 45L130 65" fill="none"/>':'<rect x="14" y="17" width="152" height="56" rx="5"/>';return `<svg viewBox="0 0 180 90" class="flow-shape ${active?'active':''}" role="img" aria-label="${esc(label)}"><g>${shape}</g>${kind!=='arrow'?`<text x="90" y="50" text-anchor="middle" direction="ltr">${esc(label)}</text>`:''}</svg>`;}
function question(q){const a=UI.answers[q.id]||'',checked=!!UI.checked[q.id],ok=normalize(a)===normalize(q.answer);return `<div class="practice-question" data-question="${q.id}"><h3>${esc(q.prompt)}</h3>${q.code?code(q.code):''}${q.options?`<div class="answer-options" role="group" aria-label="اختر الإجابة">${q.options.map((o,i)=>`<button class="answer-option ${a===o?'selected':''} ${checked&&o===q.answer?'correct':''}" data-act="answer" data-qid="${q.id}" data-option="${esc(o)}" aria-pressed="${a===o}" ${checked?'disabled':''}><span class="option-number">${String.fromCharCode(65+i)}</span><bdi>${esc(o)}</bdi><span class="px-choice-indicator" aria-hidden="true"></span></button>`).join('')}</div>`:`<label class="field-label">إجابتك<textarea dir="ltr" data-bind="answer:${q.id}" aria-label="إجابتك" placeholder="اكتب الناتج هنا" ${checked?'disabled':''}>${esc(a)}</textarea></label>`}<div class="actions">${button('check-question','تحقّق من الإجابة ✓',`data-qid="${q.id}" ${!a.trim()||checked?'disabled':''}`)}${checked?button('retry-question','حاول مرة ثانية ↺',`data-qid="${q.id}"`,'button secondary'):''}</div>${checked?feedback(ok,esc(q.explanation)+(ok?'':`<br>الإجابة الصحيحة: <bdi class="native-output">${esc(q.answer)}</bdi>`)):''}</div>`;}
function findQuestion(id){if(id.startsWith('function-')){const f=funcs[Number(id.slice(9))];return f?{id,topic:'functions',prompt:`تدرّب على ${f.name}: اكتب الناتج`,code:f.code,answer:f.result,explanation:f.desc+(f.after?` القيمة المعادة ${f.result}، والقائمة الآن ${f.after}.`:''),marks:1}:null;}return Object.values(lessonChecks).find(q=>q.id===id)||originalOutputs.find(q=>q.id===id)||mockQuestions.find(q=>q.id===id);}
function lessonView(id){const index=lessons.findIndex(l=>l.id===id);if(index<0)return catalogView();const l=lessons[index],done=P.completed.includes(id),check=lessonChecks[id],passed=UI.checked[check.id]&&normalize(UI.answers[check.id])===normalize(check.answer),next=lessons[index+1];const activity=id==='types'?typesActivity():id==='operations'?operationsActivity():id==='flowcharts'?flowActivity():id==='conditions'?conditionsActivity():id==='loops'?loopsActivity():functionsActivity();return `<div class="container lesson-layout"><aside class="lesson-sidebar"><a class="text-button px-catalog-return" href="#/learn/"><svg class="px-return-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 12h16m-6-6 6 6-6 6"/></svg><span>العودة إلى الفهرس</span></a><div class="sidebar-title">خطوة بخطوة نحو الإتقان</div>${lessons.map((x,i)=>`<a class="sidebar-lesson ${x.id===id?'active':''}" href="#/learn/${x.id}/" ${x.id===id?'aria-current="page"':''}><span>${P.completed.includes(x.id)?'✓':i+1}</span>${x.title}</a>`).join('')}${tip('كل تجربة محدّدة وآمنة؛ لا تنفّذ هذه النسخة كود بايثون حرًّا.')}</aside><article class="lesson-main">${pageHeading(`الدرس 0${index+1} · <bdi>${l.en}</bdi>`,l.title,l.description)}<span class="stage-detail">${l.minutes} دقائق تقديرية</span><section class="panel activity-panel lesson-tool ${id}-workspace"><div class="panel-heading"><span class="number-badge">01</span><div><small>${lessonPresentation[id].label}</small><h2>${lessonPresentation[id].title}</h2></div></div>${activity}</section><section class="panel activity-panel"><div class="panel-heading"><span class="number-badge teal">02</span><div><small>وقفة سريعة</small><h2>تأكّد من فهمك</h2></div></div>${question(check)}</section><div class="lesson-complete panel"><div><h3>${done?'أتممت هذا الدرس، أحسنت!':'خطوة جديدة نحو الإتقان'}</h3><p>${done?'يمكنك العودة للتجربة في أي وقت.':'أجب عن سؤال الفهم بشكل صحيح لإكمال الدرس.'}</p></div>${done?link(next?'/learn/'+next.id+'/':'/exam/',next?'الدرس التالي':'طبّق على الامتحان','button'):button('complete-lesson','أكملت الدرس ✓',`data-id="${id}" ${!passed?'disabled':''}`)}</div><details class="reference-page panel" id="lesson-reference"><summary><span>من صفحات مذكرة تقن الأصلية</span><small>افتح المرجع البصري للدرس</small></summary><div>${image('/references/pages/'+id+'.webp','صفحة '+l.title+' من مذكرة تقن')}<p>صورة مرجعية من الملفات المرفقة؛ النشاط أعلاه هو مساحة التجربة.</p></div></details></article></div>`;}
function typesActivity(){return typeComparisonWorkspace();}
function operationsActivity(){return calculationWorkspace();}
function flowActivity(){return diagramStudio();}
function compare(sm,op){return {'<':sm<100,'>':sm>100,'==':sm===100,'!=':sm!==100,'>=':sm>=100,'<=':sm<=100}[op];}
function conditionsActivity(){return decisionWorkspace();}
function loopsActivity(){return `<div class="for-loop-lesson">
 <div class="for-loop-idea"><h3>أمر واحد، يتكرّر لكل قيمة.</h3><p>تأخذ <code dir="ltr">for</code> قيمة من <code dir="ltr">range()</code>، ثم تنفّذ الأوامر المزاحة إلى الداخل. تنتقل بعدها إلى القيمة التالية.</p><div class="for-loop-cycles" aria-label="قيم التكرار في مثال المنهج">${[5,7,9].map((n,i)=>'<span><small>الدورة '+(i+1)+'</small><bdi>'+n+'</bdi></span>').join('')}</div></div>
 <div class="for-loop-anatomy">${code('for i in range(5, 10, 2):\n    print(i)')}<dl><div><dt><code dir="ltr">i</code></dt><dd>يحمل قيمة الدورة الحالية.</dd></div><div><dt><code dir="ltr">range()</code></dt><dd>تجهّز القيم: 5 ثم 7 ثم 9.</dd></div><div><dt>المسافة البادئة</dt><dd>الأوامر المزاحة للداخل هي التي تتكرّر.</dd></div></dl></div>
 <div class="for-loop-after"><strong>ما الذي يُنفَّذ بعد الحلقة؟</strong><p>بعد آخر دورة، يكمل البرنامج الأسطر غير المزاحة إلى الداخل. في مثال المذكرة، نحسب <code dir="ltr">z</code> ثم نطبعها.</p></div>
 <details class="loop-laboratory ft-trace-lab" id="loop-lab"><summary><span><small>مثال المنهج · مذكرة تقن 107، ص 7</small><strong>تتبّع التكرار، خطوة بخطوة.</strong></span><span class="ft-lab-disclosure"><span>13 خطوة</span><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m6 9 6 6 6-6"/></svg></span></summary><div class="ft-trace-body"><p class="ft-trace-intro">راقب السطر المظلّل والقيم بعد تنفيذه. المثال يعمل بثلاث دورات فقط.</p>${executionTimeline(true)}</div></details>
</div>`;}

function functionsActivity(){return functionLaboratory();}
function loopVisualizer(){return executionTimeline();}
function stopLoop(){if(timer)clearInterval(timer);timer=null;UI.playing=false;}
function checkActions(group,ready=true){const done=!!UI.checked[group];return `<div class="actions">${button('check-original','تحقّق من الحل ✓',`data-group="${group}" ${!ready||done?'disabled':''}`)}${done?button('retry-original','إعادة المحاولة ↺',`data-group="${group}"`,'button secondary'):''}</div>`;}
function v(key,fallback=''){return UI.values[key]??fallback;}
function valSelect(key,label,options,disabled=false){return `<select data-bind="${key}" aria-label="${esc(label)}" ${disabled?'disabled':''}><option value="">اختر</option>${options.map(o=>`<option value="${esc(o)}" ${v(key)===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;}
function flowQuestion(){const done=!!UI.checked['original-1'],r=flowAnswer();return `<p>أدخل أربعة أرقام من اختيارك. لا يفرض السؤال قيمًا بعينها.</p><div class="exam-flow">${flowShape('start','البداية',done&&UI.flowStep===0)}<span class="down-arrow" aria-hidden="true">↓</span><label class="flow-input" dir="ltr">Ltest = ${input('q1.list','قائمة من أربعة أرقام',v('q1.list'),'text',`placeholder="[ …, …, …, … ]" ${done?'disabled':''}`)}</label><span class="down-arrow" aria-hidden="true">↓</span><label class="field-label" dir="ltr">sm = ${valSelect('q1.sum','عملية حساب المجموع',['sum(Ltest)','len(Ltest)','max(Ltest)'],done)}</label><span class="down-arrow" aria-hidden="true">↓</span>${valSelect('q1.condition','شرط القرار',['sm < 100','sm > 100','sm == 100'],done)}${flowShape('decision',v('q1.condition')||'الشرط؟',done&&UI.flowStep===2)}<label class="field-label">المسار المؤدي إلى «مجموع الدرجات أقل من 100»${valSelect('q1.branch','مسار أقل من 100',['Yes','No'],done)}</label><div class="flow-branches"><div class="branch ${done&&UI.flowStep===3?'selected':''}"><span>${done?'Yes':v('q1.branch')||'؟'}</span><p>مجموع الدرجات أقل من 100</p></div><div class="branch"><span>${done?'No':v('q1.branch')?(v('q1.branch')==='Yes'?'No':'Yes'):'؟'}</span><p>انتبه، مجموع الدرجات تجاوز 100</p></div></div>${flowShape('end','النهاية',done&&UI.flowStep===4)}</div>${checkActions('original-1',['q1.list','q1.sum','q1.condition','q1.branch'].every(k=>v(k)))}${done?feedback(r,'تُقبل أي قائمة من أربعة أعداد. نحسب sum(Ltest)، ثم نختبر sm &lt; 100. Yes للأصغر، وNo لغير ذلك.')+tip('صياغة «تجاوز 100» هي الرسالة الأصلية. عند المجموع 100 أيضًا نصل إليها لأن الشرط يستخدم &lt;.')+`<div class="walkthrough"><strong>شرح الخطوة ${UI.flowStep+1} من 5</strong><p>${['نبدأ تنفيذ البرنامج.','نعيّن القائمة ونحسب مجموعها.','نختبر هل المجموع أقل من 100.','نختار Yes إذا تحقق الشرط، وإلا No، ثم نعرض الرسالة.','يلتقي المساران في النهاية.'][UI.flowStep]}</p>${button('flow-step','الخطوة التالية ←','','text-button')}</div>`:''}`;}
function validList(s){return /^\[\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:\s*,\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)){3}\s*\]$/.test(String(s).trim());}
function flowAnswer(){return validList(v('q1.list'))&&v('q1.sum')==='sum(Ltest)'&&v('q1.condition')==='sm < 100'&&v('q1.branch')==='Yes';}
function typesQuestion(){const done=!!UI.checked['original-2'],ok=originalTypes.every((t,i)=>v('q2.'+i)===t);return `${code(originalTypesCode)}<div class="table-scroll"><table class="classification"><thead><tr><th>المتغيّر</th><th>اختر نوع البيانات</th>${done?'<th>المراجعة</th>':''}</tr></thead><tbody>${['a','b','c','d','e'].map((x,i)=>`<tr><th><code>${x}</code></th><td><div class="chips" dir="ltr">${['int','float','str','bool','list'].map(t=>button('classify',t,`data-index="${i}" data-type="${t}" aria-pressed="${v('q2.'+i)===t}" ${done?'disabled':''}`,v('q2.'+i)===t?'chip selected':'chip')).join('')}</div></td>${done?`<td class="${v('q2.'+i)===originalTypes[i]?'topic-correct':'topic-error'}">${v('q2.'+i)===originalTypes[i]?'✓ صحيح':'الصحيح: '+originalTypes[i]}</td>`:''}</tr>`).join('')}</tbody></table></div>${checkActions('original-2',originalTypes.every((t,i)=>v('q2.'+i)))}${done?feedback(ok,'القائمة list؛ تحويل input عبر int ينتج int؛ input وحدها str؛ العنصر الثالث True من النوع bool؛ والقسمة / تنتج float.') :''}`;}
function traceQuestion(){const done=!!UI.checked['original-3'],ok=traceRows.every((r,i)=>['i','x','y'].every(k=>String(v('q3.'+i+'.'+k))===String(r[k])))&&v('q3.z')==='35';return `<div class="trace-answer-grid">${code(loopCode)}<div class="table-scroll"><table><thead><tr><th>التكرار</th><th>i</th><th>x</th><th>y</th></tr></thead><tbody>${traceRows.map((r,i)=>`<tr><th>${i+1}</th>${['i','x','y'].map(k=>`<td>${input('q3.'+i+'.'+k,`${k} في التكرار ${i+1}`,v('q3.'+i+'.'+k),'number',done?'disabled':'')}${done?`<small class="answer-key">${r[k]}</small>`:''}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><label class="field-label" dir="ltr">z = ${input('q3.z','قيمة z النهائية',v('q3.z'),'number',done?'disabled':'')}</label>${checkActions('original-3',traceRows.every((r,i)=>['i','x','y'].every(k=>v('q3.'+i+'.'+k)!==''))&&v('q3.z')!=='')}${done?feedback(ok,'قيم i هي 5، 7، 9. نطرح i من x ونزيد y بمقدار 2. في النهاية x = 29 وy = 6، إذن z = 35.')+loopVisualizer():''}`;}
function completionQuestion(){const done=!!UI.checked['original-5'],earned=completion.reduce((s,[k,a,m])=>s+(String(v('q5.'+k)).trim()===a?m:0),0),blank=k=>input('q5.'+k,'أكمل '+k,v('q5.'+k),'text',`class="code-blank" dir="ltr" ${done?'disabled':''}`),word=v('q5.demo','Ali');return `<h3>أ. الأعداد الزوجية بين 4 و102 · 3 درجات</h3><p>يعرض البرنامج الأعداد الزوجية ابتداءً من 4 وحتى ما قبل 102.</p><div class="completion-code" dir="ltr">for v ${blank('in')} ${blank('range')}(${blank('start')}, ${blank('stop')}, ${blank('step')}):<br>    print(v)</div><h3>ب. إدخال كلمة وإضافتها إلى القائمة · 5 درجات</h3><p>إذا كان طول الكلمة أقل من 5 أحرف تُضاف إلى k، فيما عدا ذلك تُطبع الكلمة.</p><div class="completion-code" dir="ltr">k = []<br>txt = input("word: ")<br>if ${blank('len')}(${blank('txt')}) ${blank('op')} ${blank('limit')}:<br>    k.${blank('append')}(${blank('word')})<br>${blank('else')}:<br>    print(txt)</div>${checkActions('original-5',completion.every(([k])=>String(v('q5.'+k)).trim()))}${done?feedback(earned===8,`درجتك: ${earned} / 8 وفق توزيع الفراغات في المصدر. `+completion.filter(([k,a])=>String(v('q5.'+k)).trim()!==a).map(([k,a])=>esc(k)+': '+esc(a)).join('، '))+`<div class="sequence" dir="ltr">4 → 6 → 8 → … → 98 → 100</div>${code('for v in range(4, 102, 2):\n    print(v)\n\nk = []\ntxt = input("word: ")\nif len(txt) < 5:\n    k.append(txt)\nelse:\n    print(txt)')}<label class="field-label">جرّب كلمة${input('q5.demo','جرّب كلمة',word,'text','maxlength="40"')}</label><div class="function-output" role="status">${Array.from(word).length<5?'تُضاف إلى القائمة k':'تُطبع الكلمة'}: <bdi>${esc(word)}</bdi></div>`:''}`;}
function errorQuestion(e,i){const done=!!UI.checked[e.id],t=v(e.id),ok=t===e.bad;return `<div class="error-exercise"><h3>المثال ${i+1} · درجتان</h3>${code(e.code)}<p>حدّد العبارة أو الرمز المسبّب للخطأ.</p><div class="chips" dir="ltr">${e.tokens.map(token=>button('error-token',esc(token),`data-id="${e.id}" data-token="${esc(token)}" aria-pressed="${t===token}" ${done?'disabled':''}`,t===token?'chip selected':'chip')).join('')}</div><label class="field-label">اقترح بديلًا صحيحًا (للتعلّم، لا يدخل في الدرجة)${input(e.id+'.replacement','اقترح بديلًا صحيحًا',v(e.id+'.replacement'),'text',`dir="ltr" ${done?'disabled':''}`)}</label>${checkActions(e.id,!!t)}${done?feedback(ok,esc(e.why)+`<br>موضع الخطأ: <bdi>${esc(e.bad)}</bdi>. البديل المقترح: <bdi>${esc(e.replacement)}</bdi>.`)+code(e.fix):''}</div>`;}
function examView(){return guidedExamWorkspace();}
function partNavigator(kind,items,index){return `<div class="part-navigation"><div><span class="ed-label">${kind==='output'?'توقّع المخرجات':'مختبر تصحيح الأخطاء'}</span><span>الجزء ${index+1} من ${items.length}</span></div><div role="group" aria-label="اختر جزء السؤال">${items.map((x,i)=>{const done=!!UI.checked[x.id],ok=done&&(kind==='output'?correct(x,UI.answers[x.id]):v(x.id)===x.bad);return button('exam-part',`${i+1}${done?(ok?' ✓':' ↻'):''}`,`data-kind="${kind}" data-index="${i}" aria-pressed="${i===index}"`,i===index?'active':done&&ok?'complete':'');}).join('')}</div></div>`;}
function partActions(kind,index,count){return `<div class="part-actions">${button('exam-part','الجزء السابق',`data-kind="${kind}" data-index="${Math.max(0,index-1)}" ${index===0?'disabled':''}`,'button secondary')}${index<count-1?button('exam-part','الجزء التالي ←',`data-kind="${kind}" data-index="${index+1}"`):'<span>وصلت إلى آخر جزء في هذا السؤال.</span>'}</div>`;}
function debuggingCode(e){const id=clips.push(e.code)-1,chosen=v(e.id),done=!!UI.checked[e.id],tokens=[...e.tokens].sort((a,b)=>b.length-a.length),pattern=new RegExp('('+tokens.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','g');return `<div class="code-window ed-code debug-code" dir="ltr"><div class="code-toolbar"><small>PYTHON / SELECT THE ISSUE</small><button class="copy-code" data-act="copy" data-id="${id}" aria-label="نسخ كود بايثون">نسخ ⧉</button></div><pre><code>${e.code.split('\n').map((line,i)=>`<span class="code-line"><span class="line-number" aria-hidden="true">${i+1}</span>${line.split(pattern).filter(Boolean).map(t=>e.tokens.includes(t)?`<button data-act="error-token" data-id="${e.id}" data-token="${esc(t)}" aria-label="اختر الرمز ${esc(t)}" aria-pressed="${chosen===t}" class="debug-token ${chosen===t?'chosen':''} ${done&&t===e.bad?'actual-error':''}" ${done?'disabled':''}>${esc(t)}</button>`:syntax(t)).join('')}</span>`).join('')}</code></pre></div>`;}
function debuggingWorkspace(e,i){const done=!!UI.checked[e.id],ok=v(e.id)===e.bad;return `<div class="error-exercise"><div class="debugging-prompt"><h3>المثال ${i+1} · درجتان</h3><p>اضغط على العبارة أو الرمز المسبّب للخطأ داخل الكود. تقدر تستخدم Tab ثم Enter.</p></div>${debuggingCode(e)}<div class="debug-selection" role="status">${v(e.id)?'حدّدت: <bdi>'+esc(v(e.id))+'</bdi>':'اختر موضع الخطأ، ثم تحقّق من اختيارك.'}</div><label class="field-label">اقترح بديلًا صحيحًا (للتعلّم، لا يدخل في الدرجة)${input(e.id+'.replacement','اقترح بديلًا صحيحًا',v(e.id+'.replacement'),'text',`dir="ltr" ${done?'disabled':''}`)}</label>${checkActions(e.id,!!v(e.id))}${done?feedback(ok,esc(e.why)+`<br>موضع الخطأ: <bdi>${esc(e.bad)}</bdi>. البديل المقترح: <bdi>${esc(e.replacement)}</bdi>.`)+`<div class="debug-correction"><span class="ed-label">أحد التصحيحات الصحيحة</span>${code(e.fix)}</div>`:''}</div>`;}
function guidedExamWorkspace(){const g=originalGroups[UI.exam],oi=UI.outputPart||0,ei=UI.errorPart||0;let workspace;if(UI.exam===0)workspace=flowQuestion();else if(UI.exam===1)workspace=typesQuestion();else if(UI.exam===2)workspace=traceQuestion();else if(UI.exam===3)workspace=partNavigator('output',originalOutputs,oi)+question(originalOutputs[oi]).replace('class="practice-question"','class="practice-question output-question"')+partActions('output',oi,originalOutputs.length);else if(UI.exam===4)workspace=completionQuestion();else workspace=partNavigator('error',errorExamples,ei)+debuggingWorkspace(errorExamples[ei],ei)+partActions('error',ei,errorExamples.length);const tried=new Set(P.practice.filter(a=>a.questionId.startsWith('original-')).map(a=>a.questionId.split('-')[1])).size;return `<div class="container page-content">${pageHeading('المرحلة 02 / مساحة للتفكير','حل الامتحان السابق','ستة أسئلة أصلية. حلّ بنفسك، ثم راجع خطواتك.')}<div class="source-note"><span>40 درجة <b>·</b> جرّبت ${tried} من 6 أسئلة رئيسية</span>${button('source-dialog','عرض المصدر ↗','','text-button')}</div><div class="exam-tabs" role="group" aria-label="اختر سؤالًا">${originalGroups.map((x,i)=>`<button data-act="exam-tab" data-index="${i}" class="${UI.exam===i?'selected':''}" aria-pressed="${UI.exam===i}"><span>0${i+1}</span>${x.title}<small>${x.marks} درجات</small></button>`).join('')}</div><div class="original-layout"><aside class="question-instructions panel"><span class="eyebrow">السؤال ${UI.exam+1} / 6</span><h2>${g.title}</h2><span class="pill">${g.marks} درجات</span><p>${esc(g.statement)}</p>${tip('النص والدرجات من المصدر الأصلي. التوضيح يظهر بعد إرسال إجابتك؛ ويمكنك إعادة المحاولة.')}</aside><section class="panel activity-panel question-specific question-kind-${UI.exam}" aria-label="مساحة حل السؤال ${UI.exam+1}">${workspace}</section></div><div class="page-bottom-actions">${button('exam-prev','السؤال السابق',UI.exam===0?'disabled':'','button secondary')}${UI.exam<5?button('exam-next','السؤال التالي ←'):link('/mock-exam/','انتقل للاختبار التجريبي','button')}</div></div>`;}
function questionMapButtons(){if(!P.draft)return '';const d=P.draft;return `<div class="question-numbers">${draftQuestions().map((q,i)=>`<button data-act="mock-index" data-index="${i}" class="${d.answers[q.id]?'answered':''} ${i===d.index?'current':''}" ${i===d.index?'aria-current="step"':''} aria-label="السؤال ${i+1}${d.answers[q.id]?'، مجاب':''}${d.flags.includes(q.id)?'، للمراجعة':''}">${i+1}${d.flags.includes(q.id)?'<small aria-hidden="true">⚑</small>':''}</button>`).join('')}</div>`;}
function assessmentChrome(){const active=!!(path.startsWith('/mock-exam')&&P.draft);$('#site').classList.toggle('active-assessment',active);let label=$('#assessment-nav-label'),exit=$('#assessment-exit');if(!label){label=document.createElement('span');label.id='assessment-nav-label';label.className='assessment-nav-label';$('#navigation').insertBefore(label,$('#nav-start'));exit=document.createElement('a');exit.id='assessment-exit';exit.href='#/';exit.className='assessment-exit';exit.textContent='حفظ وخروج ↗';$('#navigation').insertBefore(exit,$('#menu-toggle'));}label.hidden=!active;exit.hidden=!active;$('#nav-start').hidden=active;$('#menu').hidden=active;$('#menu-toggle').hidden=active;if(active){const d=P.draft,n=draftQuestions().filter(q=>d.answers[q.id]?.trim()).length;label.textContent=`اختبار تدريبي · ${n}/${d.questionIds.length} إجابات محفوظة`;}}
function recommendationPath(topic,a){if(topic==='loops')return '/learn/loops/?focus=loops';const first=attemptQuestions(a).find(q=>q.topic===topic&&!correct(q,a.answers[q.id])),fn={'mock-11':'abs','mock-12':'len','mock-13':'pop','mock-14':'sum','mock-15':'range','mock-16':'sorted','mock-19':'max','mock-20':'int'}[first?.id];return '/learn/'+lessonFor[topic]+'/'+(fn?'?function='+fn:'');}
function recommendationReason(topic,a){const bad=attemptQuestions(a).filter(q=>q.topic===topic&&!correct(q,a.answers[q.id])),q=bad[0],specific={'mock-1':'ابدأ بالفرق بين العدد الصحيح والنص.','mock-2':'راجع لماذا تعيد input() نصًا.','mock-3':'راجع نوع نتيجة القسمة /.','mock-4':'راجع فهرسة القائمة والقيم المنطقية.','mock-8':'راجع التقريب نحو الأسفل في //.','mock-9':'راجع معنى باقي القسمة %.','mock-11':'راجع القيمة المطلقة بعد الطرح.','mock-12':'راجع عدّ أحرف النص بـ len().','mock-13':'راجع الفرق بين فهرس العنصر وقيمته في pop().','mock-14':'راجع جمع عناصر القائمة.','mock-15':'تتبّع كيف تتغيّر قيمة المجموع داخل for.','mock-16':'راجع أن sorted() تعيد قائمة جديدة.','mock-17':'نفّذ التقريب قبل القسمة الأرضية.','mock-19':'راجع حساسية أسماء الدوال لحالة الأحرف.','mock-20':'حوّل النص إلى عدد قبل الجمع.'};return {count:bad.length,text:specific[q?.id]||({flowcharts:'راجع أشكال المخطط والشرط الذي يحدّد المسار.',conditions:'اختبر المساواة عند حدّ الشرط، وحدّد الفرع المنفّذ.',functions:'نفّذ مثال الدالة ولاحظ أثرها في القيمة أو القائمة.',errors:'حدّد سبب الخطأ قبل اختيار التصحيح.'}[topic]||'ارجع للفكرة وجرّب مثالًا قصيرًا.')};}
function reviewDetails(a,qs){const wrong=qs.filter(q=>!correct(q,a.answers[q.id])),filter=UI.reviewFilter||'wrong',shown=filter==='all'?qs:wrong;return `<section class="results-review"><div class="review-filter" role="group" aria-label="فلتر مراجعة الإجابات">${button('review-filter',`غير الصحيحة (${wrong.length})`,`data-filter="wrong" aria-pressed="${filter==='wrong'}"`,filter==='wrong'?'chip selected':'chip')}${button('review-filter',`كل الإجابات (${qs.length})`,`data-filter="all" aria-pressed="${filter==='all'}"`,filter==='all'?'chip selected':'chip')}</div>${shown.map((q,i)=>{const ok=correct(q,a.answers[q.id]);return `<details class="review-detail ${ok?'correct':'needs-review'}" id="review-${q.id}" ${i===0?'open':''}><summary><span>السؤال ${qs.indexOf(q)+1} / ${topicLabels[q.topic]}</span><strong>${ok?'✓ صحيح':a.answers[q.id]?'تحتاج مراجعة':'بدون إجابة'}</strong><span aria-hidden="true">+</span></summary><div><h3>${esc(q.prompt)}</h3>${q.code?code(q.code):''}<div class="answer-comparison"><p><span>إجابتك</span><bdi>${esc(a.answers[q.id]||'لم تجب')}</bdi></p><p><span>الإجابة الصحيحة</span><bdi>${esc(q.answer)}</bdi></p></div><p>${esc(q.explanation)}</p>${ok?'':link(recommendationPath(q.topic,a),'راجع الفكرة')}</div></details>`;}).join('')}${!shown.length?'<div class="no-review-errors"><h3>كل الإجابات صحيحة.</h3><p>يمكنك فتح «كل الإجابات» لمراجعة الحلول.</p></div>':''}</section>`;}
function performanceStory(){const a=selectedAttempt();if(!a)return `<div class="container page-content empty-state"><span class="large-icon" aria-hidden="true">◎</span><h1>نتيجتك تبدأ بمحاولة.</h1><p>لم تُكمل اختبارًا بعد. ابدأ التدريب، ثم ارجع هنا لتشوف فهمك حسب الموضوع وخطوتك القادمة.</p><div class="actions centered">${link('/mock-exam/','اختبر مستواك','button')}${link('/learn/','راجع الأساسيات','button secondary')}</div></div>`;const qs=attemptQuestions(a),r=score(qs,a.answers),weak=weakTopics(a),strengths=Object.entries(r.topics).filter(([,t])=>t.earned===t.total),same=b=>b.questionIds.length===a.questionIds.length&&b.questionIds.every(id=>a.questionIds.includes(id)),prior=P.attempts.slice(0,P.attempts.indexOf(a)).reverse().find(same),previous=prior?score(attemptQuestions(prior),prior.answers).percent:null;return `<div class="container page-content performance-story"><div class="section-heading"><div class="page-heading"><span class="eyebrow">النتيجة ليست نهاية الرحلة</span><h1>نتيجتك في الاختبار التجريبي</h1><p>${qs.length===20?'اختبار شامل · 40 درجة':'إعادة مركّزة · '+r.total+' درجة'} · ${new Date(a.at).toLocaleDateString('ar-BH',{timeZone:'Asia/Bahrain'})}</p></div><label class="attempt-select">محاولاتك<select data-bind="attempt" aria-label="محاولاتك">${P.attempts.map((b,i)=>{const s=score(attemptQuestions(b),b.answers);return `<option value="${esc(b.id)}" ${b.id===a.id?'selected':''}>المحاولة ${i+1} · ${s.earned}/${s.total}</option>`;}).join('')}</select></label></div><section class="result-hero panel"><div class="score-ring" style="--score:${r.percent}" role="img" aria-label="${r.percent} بالمئة"><div><strong>${r.earned}<small>/${r.total}</small></strong><span>${r.percent}%</span></div></div><div class="result-message"><span class="eyebrow">نتيجتك الفعلية، من إجاباتك.</span><h2>${readiness(r.percent)}</h2><p>${weak.length?'كل خطأ يحدّد لك فكرة تستحق المراجعة. ابدأ بالخطوة المقترحة أدناه، ثم جرّب الإعادة المركّزة.':'أتقنت هذه المحاولة. حافظ على جاهزيتك بتطبيق ما فهمته على الامتحان الأصلي.'}</p><div class="result-counts"><span><b>${r.correct}</b>صحيحة</span><span><b>${r.incorrect}</b>غير صحيحة</span><span><b>${r.unanswered}</b>بدون إجابة</span></div>${previous!==null?`<span class="improvement">مقارنة بمحاولة مماثلة: ${r.percent-previous>0?'+':''}${r.percent-previous} نقطة مئوية</span>`:''}</div></section>${strengths.length?`<div class="strengths-line"><span>نقاط قوة مؤكدة:</span>${strengths.slice(0,3).map(([t])=>`<strong>✓ ${topicLabels[t]}</strong>`).join('')}${strengths.length>3?'<small>وغيرها في التفاصيل</small>':''}</div>`:''}<section class="revision-path"><div class="revision-path-title"><span class="eyebrow">خطة مبنية على إجاباتك</span><h2>${weak.length?'خطوتك القادمة، بوضوح.':'جاهز للتطبيق من جديد.'}</h2></div>${weak.length?weak.map(([t,v],i)=>{const reason=recommendationReason(t,a);return `<article class="revision-action ${i===0?'priority':''}"><span class="revision-order">0${i+1}</span><div><small>${i===0?'ابدأ هنا':'ثم راجع'} · ${v.earned}/${v.total} درجات</small><h3>${topicLabels[t]}</h3><p>${reason.text}</p><span>${reason.count} أسئلة غير صحيحة أو بدون إجابة.</span></div>${link(recommendationPath(t,a),t==='loops'?'راجع درس التكرار':'راجع الفكرة',i===0?'button':'ed-text-link')}</article>`;}).join(''):`<div class="revision-perfect"><p>كل إجاباتك صحيحة. طبّق على الأسئلة الأصلية للحفاظ على فهمك.</p>${link('/exam/','حل الامتحان السابق','button')}</div>`}${weak.length?`<div class="revision-retake"><p>بعد المراجعة، اختبر الموضوعات نفسها من بنك التدريب.</p>${button('targeted-dialog','إعادة مركّزة على نقاط الضعف ↺')}</div>`:''}</section><details class="performance-details" id="performance-details"><summary><span><strong>تفاصيل أدائك حسب الموضوع</strong><small>${Object.keys(r.topics).length} موضوعات · درجات فعلية</small></span><span aria-hidden="true">+</span></summary><div class="mastery-list">${Object.entries(r.topics).map(([t,v])=>`<div><div class="progress-label"><span>${topicLabels[t]}</span><bdi>${v.earned} / ${v.total}</bdi></div>${progress(v.earned/v.total*100,topicLabels[t])}</div>`).join('')}</div></details><div class="actions result-review-actions">${button('review-results',UI.review?'إخفاء التفاصيل':'راجع إجاباتك والحلول','','button secondary')}${link('/mock-exam/','اختبار جديد')}</div>${UI.review?reviewDetails(a,qs):''}<p class="results-note">هذه قراءة تدريبية وليست تقديرًا رسميًا. الإعادة المركّزة تستخدم أسئلة من نفس بنك التدريب.</p></div>`;}
function refreshDecisionWorkspace(){const yes=compare(UI.sm,UI.comparison),header=$('.range-header');if(!header)return;$('output',header).textContent=UI.sm;const flow=$('.live-flow'),branch=UI.comparison+'|'+yes;if(flow){if(flow.dataset.branch!==branch){flow.innerHTML=decisionCanvas(UI.sm,UI.comparison);flow.dataset.branch=branch;}else $('svg',flow)?.setAttribute('aria-label',UI.sm+' '+UI.comparison+' 100: '+(yes?'True، مسار Yes':'False، مسار No'));}const status=$('#decision-status');if(status)status.innerHTML=`<div><strong dir="ltr">${UI.sm} ${esc(UI.comparison)} 100 → ${yes?'True':'False'}</strong><p>${UI.sm===100&&UI.comparison==='<'?'100 ليست أصغر من 100، ولذلك نتبع مسار No.':'الشرط '+(yes?'متحقق، فننفّذ if.':'غير متحقق، فننفّذ else.')}</p></div>`;$$('[data-act="set-sum"]').forEach(b=>{const active=Number(b.dataset.value)===UI.sm;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});$$('#condition-code .code-line').forEach((line,i)=>{const active=i===(yes?1:3);line.classList.toggle('highlighted',active);if(active)line.setAttribute('aria-current','step');else line.removeAttribute('aria-current');});}
function applyRouteFocus(){if(!UI.focusRequested)return;const target=UI.focusRequested;UI.focusRequested='';requestAnimationFrame(()=>{if(path!==target)return;const lab=$('#loop-lab');if(lab){lab.open=true;lab.scrollIntoView({behavior:'instant',block:'start'});$('summary',lab)?.focus({preventScroll:true});}});}
// 08. EXAMINATION ENGINE — answered state and flags persist after every change.
function draftQuestions(){return P.draft?P.draft.questionIds.map(id=>mockQuestions.find(q=>q.id===id)).filter(Boolean):mockQuestions;}
function startExam(ids=mockQuestions.map(q=>q.id)){P.draft={answers:{},flags:[],index:0,questionIds:ids,startedAt:new Date().toISOString()};save();navigate('/mock-exam/');}
function examInstructions(){return `<section class="px-exam-guidance" id="ux-exam-instructions" aria-labelledby="exam-guidance-title">
 <div class="px-guidance-heading"><span class="px-guidance-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/></svg></span><div><h2 id="exam-guidance-title">تعليمات الاختبار</h2><p>أربع نقاط قبل أن تبدأ.</p></div></div>
 <ol class="px-guidance-grid">
  <li><span aria-hidden="true">1</span><div><h3>راجع قبل التسليم</h3><p>يمكنك تعديل إجاباتك والتنقّل وتعليم الأسئلة للمراجعة.</p></div></li>
  <li><span aria-hidden="true">2</span><div><h3>الحلول بعد التسليم</h3><p>تظهر الإجابات الصحيحة بعد تأكيد تسليم المحاولة فقط.</p></div></li>
  <li><span aria-hidden="true">3</span><div><h3>حفظ على هذا الجهاز</h3><p class="px-guidance-save">تُحفظ إجاباتك في هذا المتصفح لتعود وتكملها.</p></div></li>
  <li><span aria-hidden="true">4</span><div><h3>خذ وقتك</h3><p>الوقت المقترح <bdi dir="ltr">25–35</bdi> دقيقة، دون مؤقّت إلزامي.</p></div></li>
 </ol><p class="px-guidance-footnote">تدريب للمراجعة، وليس امتحانًا رسميًا محميًا.</p>
</section>`;}

function mockView(){if(!P.draft)return `<div class="container page-content"><div class="mock-intro"><span class="large-icon" aria-hidden="true">◎</span><span class="eyebrow">المرحلة 03 / اختبر جاهزيتك</span><h1>جاهز للتحدّي؟</h1><p>خذ نفسًا، وطبّق اللي تعلّمته.<br>اختبار واحد يعطيك صورة أوضح عن مستواك.</p><div class="mock-facts"><div><b>20 سؤالًا</b><span>تغطي أفكار المراجعة</span></div><div><b>40 درجة</b><span>درجتان لكل سؤال</span></div><div><b>25–35 دقيقة</b><span>وقت مقترح، دون حد إلزامي</span></div></div><div class="panel intro-details"><h3>قبل ما تبدأ</h3><ul><li>هذه أسئلة تدريبية جديدة، وليست امتحانًا رسميًا أو أسئلة الامتحان السابق.</li><li>يمكنك التنقّل وتغيير الإجابات ووضع علامة للمراجعة.</li><li>لن تظهر الحلول في الواجهة إلا بعد التسليم.</li><li>تُحفظ الإجابات تلقائيًا على هذا المتصفح؛ ارجع وأكمل في أي وقت.</li><li>الملف محلي؛ يمكن الاطلاع على مفاتيح الإجابة في مصدره، ولا يصلح كاختبار محمي.</li></ul>${button('start-exam','ابدأ الاختبار التجريبي ↖')}</div><div class="chips centered">${['أنواع البيانات','الخرائط التدفقية','العمليات والشروط','الدوال','توقّع المخرجات','الأخطاء'].map(t=>`<span class="pill">${t}</span>`).join('')}</div></div></div>`;const d=P.draft,qs=draftQuestions(),q=qs[d.index],answered=qs.filter(x=>d.answers[x.id]?.trim()).length;return `<div class="container page-content"><div class="assessment-heading"><div><span class="eyebrow">${qs.length===20?'الاختبار التجريبي النهائي':'إعادة مركّزة على نقاط الضعف'}</span><h1>اختبار جاهزيتك</h1></div>${button('restart-exam-dialog','↺ بدء اختبار جديد','','text-button')}</div><div class="exam-progress-row"><span>السؤال ${d.index+1} من ${qs.length}</span>${progress(answered/qs.length*100,'تقدّم الاختبار')}<span>${answered} إجابات محفوظة</span></div><div class="assessment-mobile-actions">${button("mock-map-dialog","خريطة الأسئلة","","button secondary")}${button("submit-dialog","مراجعة وتسليم")}</div><div class="assessment-layout"><aside class="panel question-navigator"><h3>خريطة الأسئلة</h3><div class="question-numbers">${qs.map((x,i)=>`<button data-act="mock-index" data-index="${i}" class="${d.answers[x.id]?'answered':''} ${i===d.index?'current':''}" ${i===d.index?'aria-current="step"':''} aria-label="السؤال ${i+1}${d.answers[x.id]?'، مجاب':''}${d.flags.includes(x.id)?'، للمراجعة':''}">${i+1}${d.flags.includes(x.id)?'<small aria-hidden="true">⚑</small>':''}</button>`).join('')}</div><div class="nav-legend"><span>● تمت الإجابة</span><span>⚑ للمراجعة</span></div><p>${qs.length-answered} أسئلة بدون إجابة</p>${button('submit-dialog','تسليم الاختبار ✓')}<small>إجاباتك محفوظة تلقائيًا</small></aside><section class="panel assessment-question"><div class="question-meta"><span class="pill">${topicLabels[q.topic]}</span><span>${q.marks} درجات</span>${button('flag',d.flags.includes(q.id)?'⚑ للمراجعة':'⚐ علّم للمراجعة',`aria-pressed="${d.flags.includes(q.id)}"`,d.flags.includes(q.id)?'text-button flag-button flagged':'text-button flag-button')}</div><h2>${esc(q.prompt)}</h2>${q.code?code(q.code):''}<div class="answer-options" role="group" aria-label="اختر إجابتك">${q.options.map((o,i)=>`<button class="answer-option ${d.answers[q.id]===o?'selected':''}" data-act="mock-answer" data-option="${esc(o)}" aria-pressed="${d.answers[q.id]===o}"><span class="option-number">${String.fromCharCode(65+i)}</span><bdi>${esc(o)}</bdi></button>`).join('')}</div><div class="page-bottom-actions">${button('mock-prev','→ السابق',d.index===0?'disabled':'','button secondary')}${d.index<qs.length-1?button('mock-next','التالي ←'):button('submit-dialog','مراجعة وتسليم ✓')}</div></section></div></div>`;}
function submitDialog(){const d=P.draft;if(!d)return;const qs=draftQuestions(),answered=qs.filter(q=>d.answers[q.id]?.trim()).length;dialog('جاهز لتسليم الاختبار؟','بعد التسليم تظهر النتيجة والحلول، وتُحفظ هذه المحاولة.',`<div class="submission-counts"><div><strong>${answered}</strong>مُجاب</div><div><strong>${qs.length-answered}</strong>بدون إجابة</div><div><strong>${d.flags.length}</strong>للمراجعة</div></div>${answered<qs.length?tip('الأسئلة غير المجاب عنها تحصل على صفر.'):''}<div class="actions">${button('confirm-submit','تأكيد التسليم')}${button('close-dialog','أرجع أراجع','','button secondary')}</div>`);}
function submitExam(){if(!P.draft)return;const d=P.draft;P.attempts.push({id:globalThis.crypto?.randomUUID?.()||'attempt-'+Date.now()+'-'+P.attempts.length,at:new Date().toISOString(),answers:{...d.answers},questionIds:[...d.questionIds]});P.draft=null;UI.attemptId='';UI.review=false;save();closeDialog();navigate('/results/');}
// 09. SCORING — exact, deterministic and shared by results and recommendations.
function normalize(s){return String(s??'').replace(/\r\n/g,'\n').trim().split('\n').map(l=>l.trimEnd()).join('\n');}
function correct(q,a){return normalize(a)===normalize(q.answer);}
function score(qs,answers){let earned=0,correctCount=0,unanswered=0;const topics={};for(const q of qs){const ok=correct(q,answers[q.id]??'');if(ok){earned+=q.marks;correctCount++;}if(!String(answers[q.id]??'').trim())unanswered++;const t=topics[q.topic]??{earned:0,total:0};t.total+=q.marks;if(ok)t.earned+=q.marks;topics[q.topic]=t;}const total=qs.reduce((s,q)=>s+q.marks,0);return {earned,total,correct:correctCount,incorrect:qs.length-correctCount-unanswered,unanswered,percent:total?Math.round(earned/total*100):0,topics};}
function attemptQuestions(a){return mockQuestions.filter(q=>a.questionIds.includes(q.id));}
function readiness(p){return p>=90?'ممتاز — جاهز للمراجعة الأخيرة':p>=75?'جيد جدًا — راجع الأخطاء البسيطة':p>=60?'جيد — راجع بعض الأفكار':'ركّز على الأساسيات وحاول مرة ثانية';}
// 10. RESULTS & RECOMMENDATIONS — always based on real answers.
function selectedAttempt(){return P.attempts.find(a=>a.id===UI.attemptId)||P.attempts.at(-1);}
function weakTopics(a){const r=score(attemptQuestions(a),a.answers);return Object.entries(r.topics).filter(([,t])=>t.earned<t.total).sort((a,b)=>a[1].earned/a[1].total-b[1].earned/b[1].total);}
function resultsView(){return performanceStory();}
// 11. MOTION & SCROLL INTERACTIONS — content remains visible if animation is unavailable.
let observer=null,scrollFrame=0;const revealed=new Set();
function installReveals(){if(observer)observer.disconnect();if(matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver' in window))return;observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){revealed.add(e.target.dataset.revealKey);e.target.classList.add('reveal-ready');observer.unobserve(e.target);}});},{threshold:.07});$$('.reveal').forEach((e,i)=>{e.dataset.revealKey=path+':'+i;if(!revealed.has(e.dataset.revealKey))observer.observe(e);});updateScroll();}
function updateScroll(){cancelAnimationFrame(scrollFrame);scrollFrame=requestAnimationFrame(()=>{$('#navigation').classList.toggle('compact',scrollY>55);const section=$('#promise');if(!section)return;const words=$$('.promise-words>span',section),r=section.getBoundingClientRect(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,n=reduced?words.length:Math.ceil(Math.max(0,Math.min(1,(innerHeight-r.top)/(innerHeight+r.height*.18)))*words.length);words.forEach((word,i)=>word.classList.toggle('lit',i<n));});}
addEventListener('scroll',updateScroll,{passive:true});addEventListener('resize',updateScroll);
document.addEventListener('pointermove',e=>{const hero=e.target.closest?.('.film-hero');if(!hero||e.pointerType!=='mouse'||matchMedia('(prefers-reduced-motion: reduce), (max-width: 900px)').matches)return;const r=hero.getBoundingClientRect();hero.style.setProperty('--depth-x',((e.clientX-r.left)/r.width-.5)*-7+'px');hero.style.setProperty('--depth-y',((e.clientY-r.top)/r.height-.5)*-5+'px');},{passive:true});
// 12. ACCESSIBILITY UTILITIES
let focusBeforeDialog=null,toastTimer=0;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function dialog(title,description,body){focusBeforeDialog=document.activeElement;const d=$('#dialog');d.innerHTML=`<button class="modal-close" data-act="close-dialog" aria-label="إغلاق">×</button><h2 id="dialog-title">${esc(title)}</h2><p>${esc(description)}</p>${body}`;if(!d.open)d.showModal();}
function closeDialog(){const d=$('#dialog');if(d.open)d.close();if(focusBeforeDialog?.isConnected)focusBeforeDialog.focus({preventScroll:true});}
let clipboardSequence=0;
async function copyCode(index){const operation=++clipboardSequence,text=clips[index];if(typeof text!=='string')return;window.dispatchEvent(new CustomEvent('tgn:copy-start',{detail:{index,operation}}));try{await navigator.clipboard.writeText(text);toast('تم نسخ الكود.');}catch{const t=document.createElement('textarea');t.value=text;t.setAttribute('aria-label','كود للنسخ');t.style.cssText='position:fixed;left:-9999px;top:0';document.body.appendChild(t);t.select();let ok=false;try{ok=document.execCommand('copy');}catch{}t.remove();toast(ok?'تم نسخ الكود.':'تعذّر النسخ التلقائي؛ يمكنك تحديد الكود ونسخه يدويًا.');}finally{window.dispatchEvent(new CustomEvent('tgn:copy-done',{detail:{index,operation}}));}}
function openAsset(key){const data=ASSETS[key];if(!data)return;try{const [header,encoded]=data.split(','),bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:header.match(/data:(.*?);/)?.[1]||'application/pdf'}));window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);}catch{toast('تعذّر فتح المرجع في هذا المتصفح.');}}
$('#dialog').addEventListener('click',e=>{const d=$('#dialog');if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuOpen)closeMenu(true);});
document.addEventListener('click',e=>{const a=e.target.closest?.('a');if(a){const href=a.getAttribute('href')||'';if(href.startsWith('#')&&!href.startsWith('#/')){const target=document.getElementById(href.slice(1));if(target){e.preventDefault();target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(href==='#main')target.focus({preventScroll:true});return;}}if(href.startsWith('/references/')){e.preventDefault();openAsset(href);return;}}
const b=e.target.closest?.('[data-act]');if(!b||b.disabled)return;const act=b.dataset.act;
switch(act){
case 'journey-stage':UI.stage=Number(b.dataset.index);break;
case 'loop-jump':stopLoop();UI.step=Math.max(0,Math.min(loopStates.length-1,Number(b.dataset.index)));break;
case 'exam-part':if(b.dataset.kind==='output')UI.outputPart=Number(b.dataset.index);else UI.errorPart=Number(b.dataset.index);break;
case 'review-filter':UI.reviewFilter=b.dataset.filter;break;
case 'mock-map-dialog':dialog('خريطة الأسئلة','انتقل إلى سؤال. اللون الأخضر يعني أنه مُجاب، والعلم يعني أنه للمراجعة.',questionMapButtons());return;
case 'copy':copyCode(Number(b.dataset.id));return;
case 'select-type':UI.types=Number(b.dataset.index);break;
case 'mini-type':UI.miniType=b.dataset.type;record('type-mini-'+UI.typeQuiz,UI.miniType,UI.miniType===typeExamples[UI.typeQuiz].type);break;
case 'next-type':UI.typeQuiz=(UI.typeQuiz+1)%typeExamples.length;UI.miniType='';break;
case 'preview-op':case 'set-operator':UI.operator=b.dataset.op;break;
case 'all-lessons':UI.filter='all';break;
case 'select-shape':UI.shape=b.dataset.id;break;
case 'select-block':UI.block=b.dataset.block;break;
case 'place-block':if(UI.block){UI.slots[Number(b.dataset.slot)]=UI.block;UI.block='';UI.builderChecked=false;}else toast('اختر كتلة أولًا، ثم اضغط على الخانة.');break;
case 'check-builder':UI.builderChecked=true;record('flow-builder',JSON.stringify(UI.slots),UI.slots.every((x,i)=>x===blocks[i][0]));break;
case 'reset-builder':UI.slots=['','','','',''];UI.block='';UI.builderChecked=false;break;
case 'set-sum':UI.sm=Number(b.dataset.value);break;
case 'comparison':UI.comparison=b.dataset.op;break;
case 'select-function':stopLoop();UI.function=Number(b.dataset.index);UI.ran=false;break;
case 'run-function':UI.ran=true;if(isRangeLesson())UI.values['range.example.done']='1';break;
case 'range-value':case 'range-next-value':case 'range-prev-value':{if(!isRangeLesson())return;const current=Math.max(0,Math.min(2,Number(v('range.value.index','0'))||0)),next=b.dataset.act==='range-value'?Number(b.dataset.index):current+(b.dataset.act==='range-next-value'?1:-1);UI.values['range.value.index']=String(Math.max(0,Math.min(2,next)));if(UI.values['range.value.index']==='2')UI.values['range.values.done']='1';break;}
case 'loop-prev':stopLoop();UI.step=Math.max(0,UI.step-1);break;
case 'loop-next':stopLoop();UI.step=Math.min(loopStates.length-1,UI.step+1);break;
case 'loop-reset':stopLoop();UI.step=0;break;
case 'loop-play':if(UI.playing){stopLoop();}else{if(UI.step===loopStates.length-1)UI.step=0;UI.playing=true;timer=setInterval(()=>{if(UI.step<loopStates.length-1)UI.step++;if(UI.step===loopStates.length-1)stopLoop();render(true);},1500);}break;
case 'answer':UI.answers[b.dataset.qid]=b.dataset.option;break;
case 'check-question':{const q=findQuestion(b.dataset.qid);if(!q)return;UI.checked[q.id]=true;record(q.id,UI.answers[q.id]||'',correct(q,UI.answers[q.id]));break;}
case 'retry-question':delete UI.checked[b.dataset.qid];delete UI.answers[b.dataset.qid];break;
case 'complete-lesson':{const id=b.dataset.id,q=lessonChecks[id];if(!UI.checked[q.id]||!correct(q,UI.answers[q.id]))return;const previous=getLearningProgress(),newCompletion=!P.completed.includes(id);if(newCompletion)P.completed.push(id);P.currentLesson=lessons[lessons.findIndex(l=>l.id===id)+1]?.id||id;save();if(newCompletion)queueMicrotask(()=>window.dispatchEvent(new CustomEvent('tgn:lesson-completed',{detail:{id,previous,current:getLearningProgress(),saved:persistenceSnapshot().state==='saved'}})));break;}
case 'exam-tab':stopLoop();UI.exam=Number(b.dataset.index);break;
case 'exam-prev':stopLoop();UI.exam=Math.max(0,UI.exam-1);break;
case 'exam-next':stopLoop();UI.exam=Math.min(5,UI.exam+1);break;
case 'classify':UI.values['q2.'+b.dataset.index]=b.dataset.type;break;
case 'error-token':UI.values[b.dataset.id]=b.dataset.token;break;
case 'flow-step':UI.flowStep=(UI.flowStep+1)%5;break;
case 'retry-original':delete UI.checked[b.dataset.group];break;
case 'check-original':{const g=b.dataset.group;let ok=false;if(g==='original-1')ok=flowAnswer();else if(g==='original-2')ok=originalTypes.every((t,i)=>v('q2.'+i)===t);else if(g==='original-3')ok=traceRows.every((r,i)=>['i','x','y'].every(k=>String(v('q3.'+i+'.'+k))===String(r[k])))&&v('q3.z')==='35';else if(g==='original-5')ok=completion.every(([k,a])=>String(v('q5.'+k)).trim()===a);else{const err=errorExamples.find(x=>x.id===g);ok=!!err&&v(g)===err.bad;}UI.checked[g]=true;record(g,JSON.stringify(UI.values),ok);break;}
case 'source-dialog':dialog('ملف الامتحان يتضمّن الإجابات','يمكنك متابعة الحل، أو فتح المصدر في تبويب جديد.',`<div class="px-source-panel"><div class="actions px-source-actions">${button('close-dialog','أكمل الحل بنفسي','','button px-source-return')}${button('open-source','فتح الامتحان والإجابات','','button secondary px-source-open')}</div><div class="px-source-reference"><span>للشرح والمراجعة</span>${button('open-booklet','المذكرة الأصلية','','text-button px-source-booklet')}</div></div>`);return;
case 'open-source':closeDialog();openAsset('/references/TGN-107-AN.pdf');return;
case 'open-booklet':closeDialog();openAsset('/references/TGN-NOTE.pdf');return;
case 'start-exam':startExam();return;
case 'mock-index':if($('#dialog').open)closeDialog();if(P.draft){P.draft.index=Number(b.dataset.index);save();}break;
case 'mock-answer':if(P.draft){const q=draftQuestions()[P.draft.index];P.draft.answers[q.id]=b.dataset.option;save();}break;
case 'mock-prev':if(P.draft){P.draft.index=Math.max(0,P.draft.index-1);save();}break;
case 'mock-next':if(P.draft){P.draft.index=Math.min(draftQuestions().length-1,P.draft.index+1);save();}break;
case 'flag':if(P.draft){const id=draftQuestions()[P.draft.index].id;P.draft.flags=P.draft.flags.includes(id)?P.draft.flags.filter(x=>x!==id):[...P.draft.flags,id];save();}break;
case 'submit-dialog':submitDialog();return;
case 'confirm-submit':submitExam();return;
case 'restart-exam-dialog':dialog('نبدأ اختبارًا جديدًا؟','ستُحذف إجابات المحاولة الحالية فقط. تبقى نتائجك السابقة محفوظة.',`<div class="actions nb-dialog-actions">${button('close-dialog','إلغاء','','button secondary')}${button('confirm-restart','ابدأ من جديد')}</div>`);$('#dialog').dataset.tone='restart';return;
case 'confirm-restart':closeDialog();startExam();queueMicrotask(()=>{toast('بدأ اختبار جديد. بالتوفيق في محاولتك.');toastNode.dataset.tone='success';window.dispatchEvent(new Event('tgn:notice-ready'));});return;
case 'review-results':UI.review=!UI.review;break;
case 'targeted-dialog':{const a=selectedAttempt();if(!a)return;const weak=weakTopics(a),ids=mockQuestions.filter(q=>weak.some(([t])=>q.topic===t)).map(q=>q.id);dialog('إعادة مركّزة',`ستتدرّب على ${ids.length} سؤالًا من نفس بنك التدريب في الموضوعات الأضعف. تُحفظ النتيجة كمحاولة جديدة.${P.draft?' لديك اختبار جارٍ سيُستبدل بهذه المحاولة.':''}`,`<div class="actions">${button('confirm-targeted','ابدأ الإعادة')}${button('close-dialog','إلغاء','','button secondary')}</div>`);return;}
case 'confirm-targeted':{const a=selectedAttempt();if(!a)return;const weak=weakTopics(a),ids=mockQuestions.filter(q=>weak.some(([t])=>q.topic===t)).map(q=>q.id);if(!ids.length)return;closeDialog();startExam(ids);return;}
case 'reset-progress':dialog('هل أنت متأكد من إعادة ضبط التقدّم؟','سيتم حذف تقدّم الدروس وإجابات التدريب والمحاولات والنتائج والإنجازات المحفوظة على هذا الجهاز. لا يمكن التراجع عن هذه العملية.',`<div class="actions">${button('close-dialog','إلغاء')}${button('confirm-reset','نعم، إعادة ضبط التقدّم','','button danger')}</div>`);return;
case 'confirm-reset':protectedStoredProgress=false;P=fresh();UI.checked={};UI.answers={};UI.values={};save();closeDialog();navigate('/');queueMicrotask(()=>window.dispatchEvent(new CustomEvent('tgn:reset',{detail:productSnapshot()})));return;
case 'close-dialog':closeDialog();return;
default:return;
}
render(true);
});
function updateOperationDisplay(){const a=v('opA','9'),b=v('opB','2'),op=UI.operator,r=String(a).trim()&&String(b).trim()?operate(Number(a),Number(b),op):'أدخل عددين صالحين',shown=typeof r==='number'&&op==='/'&&Number.isInteger(r)?r+'.0':String(r),panel=$('.calculation');if(panel){$('span',panel).textContent=(a||'?')+' '+op+' '+(b||'?');$('strong',panel).textContent=shown;const comparison=$('#division-comparison');if(comparison)comparison.innerHTML=operationComparison(a,b);}}
function updateConditionDisplay(){return refreshDecisionWorkspace();}
function changeBinding(e){const el=e.target,key=el.dataset?.bind;if(!key)return;const value=el.value;if(key==='opA'||key==='opB'){UI.values[key]=value;updateOperationDisplay();return;}if(key==='sm'){UI.sm=Number(value);updateConditionDisplay();return;}if(key.startsWith('answer:'))UI.answers[key.slice(7)]=value;else if(key==='filter')UI.filter=value;else if(key==='operator')UI.operator=value;else if(key==='attempt'){UI.attemptId=value;UI.review=false;}else UI.values[key]=value;render(true);}
document.addEventListener('input',changeBinding);document.addEventListener('change',e=>{if(e.target.tagName==='SELECT')changeBinding(e);});
document.addEventListener('dragstart',e=>{const b=e.target.closest?.('[data-block]');if(b){UI.block=b.dataset.block;e.dataTransfer.setData('text/plain',UI.block);}});
document.addEventListener('dragover',e=>{if(e.target.closest?.('[data-slot]'))e.preventDefault();});
document.addEventListener('drop',e=>{const slot=e.target.closest?.('[data-slot]');if(!slot)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(blocks.some(b=>b[0]===id)){UI.slots[Number(slot.dataset.slot)]=id;UI.block='';UI.builderChecked=false;render(true);}});
