catalogView=function(){return '<div class="container page-content ux-catalog"><header class="page-heading"><span class="eyebrow">المرحلة 01 / افهم</span><h1>شنو تبي تراجع؟</h1><p>اختر فكرة. جرّبها، ثم تأكّد من فهمك.</p></header><div class="ux-topic-list">'+lessons.map((l,i)=>'<a href="#/learn/'+l.id+'/" class="ux-topic-row"><span class="ux-topic-number">0'+(i+1)+'</span><div><h2>'+l.title+'</h2><p>'+l.description+'</p></div><span class="ux-topic-state">'+(P.completed.includes(l.id)?'✓ مكتمل':l.minutes+' دقائق')+'</span><span aria-hidden="true">←</span></a>').join('')+'</div><p class="ux-catalog-next">بعد الأساسيات: '+link('/exam/','طبّق على الامتحان السابق')+'</p></div>';};
const originalPerformanceStory=performanceStory;
performanceStory=function(){const root=document.createElement('div');root.innerHTML=originalPerformanceStory();root.querySelectorAll('.revision-action').forEach((el,i)=>{if(i>=3)el.remove();});const message=root.querySelector('.result-message');if(message)message.insertAdjacentHTML('beforeend','<div class="actions ux-result-actions">'+button('review-results',UI.review?'إخفاء المراجعة':'راجع أخطاءك ←')+link('/mock-exam/','اختبر نفسك مرة ثانية','text-button')+'</div>');return root.innerHTML;};
document.addEventListener('click',e=>{if(e.target.closest?.('[data-act="confirm-reset"]')){for(const k of ['answers','values','checked'])UI[k]={};UX.step=0;UX.route='';UX.lastContext='';try{localStorage.removeItem(UX_KEY);}catch{}}},true);



// TGN notebook: a study desk built around the actual course, not a marketing template.
function notebookIndex(){const samples=['42 · True · "Ali"','9 / 2 · 9 // 2','بداية ← قرار ← نهاية','if / else','for i in range(...)','len() · pop() · range()'];return '<div class="nb-index-list">'+lessons.map((l,i)=>'<a class="nb-index-row" href="#/learn/'+l.id+'/"><span class="nb-index-no" dir="ltr">0'+(i+1)+'</span><span class="nb-index-name">'+l.title+'<small>'+esc(l.description)+'</small></span><code class="nb-index-example" dir="ltr">'+esc(samples[i])+'</code><span class="nb-index-time">'+(P.completed.includes(l.id)?'✓ مكتمل':l.minutes+' دقائق')+'</span><span class="nb-index-arrow" aria-hidden="true">↖</span></a>').join('')+'</div>';}
function notebookContinue(){const exists=getLearningProgress().completed||P.practice.length||P.draft;const route=P.draft?'/mock-exam/':UX.lastContext&&/^\/(learn|exam|mock-exam)/.test(UX.lastContext)?UX.lastContext:'/learn/'+P.currentLesson+'/';return exists?'<a class="nb-continue" href="#'+route+'"><span class="nb-continue-dot" aria-hidden="true"></span><span><strong>نكمل من آخر مرة؟</strong><small>'+(P.draft?'اختبارك الجاري محفوظ.':getLearningProgress().completed+' من '+lessons.length+' وحدات مكتملة.')+'</small></span><span aria-hidden="true">←</span></a>':'';}
homeView=function(){const op=['/','//','%'].includes(UI.operator)?UI.operator:'/',result=operate(9,2,op),explain=op==='/'?'القسمة تحتفظ بالجزء العشري.':op==='//'?'نقسم، ثم نقرّب الناتج إلى الأسفل.':'هذا هو الباقي بعد القسمة.';
return '<div class="nb-home"><section class="nb-cover nb-width"><div class="nb-cover-copy"><div class="nb-section-label"><span>تقن 107</span><i aria-hidden="true"></i><span>مراجعة البايثون</span></div><h1>نراجعها،<br><span class="nb-underlined">بالفهم.<svg viewBox="0 0 400 22" preserveAspectRatio="none" aria-hidden="true"><path d="M5 13Q160 2 395 10M18 20Q230 9 380 16"/></svg></span></h1><p>نرتّب الأفكار، ونحلّ عليها.<br>من نوع القيمة إلى آخر سطر في البرنامج.</p><div class="nb-cover-actions">'+link('/learn/'+P.currentLesson+'/','نبدأ المراجعة','button')+'<a class="nb-quiet-link" href="#/exam/">أبي أحلّ الامتحان السابق <span aria-hidden="true">↖</span></a></div>'+notebookContinue()+'<div class="nb-cover-foot"><span>ست وحدات قصيرة.</span><span>ابدأ باللي تحتاجه.</span></div></div><div class="nb-scratch"><div class="nb-scratch-top"><span>سؤال قبل البداية</span><small>العمليات / 02</small></div><div class="nb-scratch-body"><h2>نفس الرقمين.<br>ثلاث إجابات مختلفة.</h2><div class="nb-equation" dir="ltr"><span>9</span><span class="nb-equation-op">'+esc(op)+'</span><span>2</span><span class="nb-equation-equals">=</span><output aria-live="polite" aria-label="ناتج العملية">'+result+'</output></div><div class="nb-operator-tabs" dir="ltr" role="group" aria-label="اختر العملية">'+[['/','قسمة'],['//','قسمة أرضية'],['%','الباقي']].map(([symbol,label])=>button('preview-op','<code>'+symbol+'</code><span>'+label+'</span>','data-op="'+symbol+'" aria-pressed="'+(op===symbol)+'"',op===symbol?'nb-op selected':'nb-op')).join('')+'</div><p class="nb-equation-note" role="status">'+explain+'</p></div><div class="nb-scratch-bottom"><span>غيّر العلامة. لاحظ الفرق.</span><code dir="ltr">print(9 '+esc(op)+' 2)</code></div></div></section>'+
'<section class="nb-contents nb-width" id="journey"><div class="nb-contents-heading"><span class="nb-section-label">01 / الأساسيات</span><h2>الفهرس.</h2><p>وش تحتاج تراجع اليوم؟</p><span class="nb-tiny-note">كل وحدة فيها تجربة،<br>وسؤال تتأكّد فيه من فهمك.</span>'+link('/learn/','افتح مساحة المراجعة','nb-quiet-link')+'</div>'+notebookIndex()+'</section>'+
'<section class="nb-exam-section"><div class="nb-width nb-exam-layout"><div class="nb-exam-copy"><span class="nb-section-label">02 / الامتحان السابق</span><h2>جرّب تحلّها<br>قبل ما تشوف الحل.</h2><p>الأسئلة الستة من الامتحان الأصلي.<br>إجابتك أولًا؛ والشرح موجود وقت ما تحتاجه.</p>'+link('/exam/','افتح ورقة الأسئلة','button')+'<div class="nb-exam-total"><strong>40</strong><span>درجة موزّعة على<br>ستة أسئلة.</span></div></div><div class="nb-exam-index"><div class="nb-exam-index-head"><span>الورقة، سؤالًا سؤالًا</span><span>الدرجة</span></div>'+originalGroups.map((g,i)=>'<a href="#/exam/?q='+(i+1)+'"><span dir="ltr">0'+(i+1)+'</span><strong>'+g.title+'</strong><span>'+g.marks+'</span><span aria-hidden="true">←</span></a>').join('')+'</div></div></section>'+
'<section class="nb-final nb-width"><div class="nb-final-copy"><span class="nb-section-label">03 / الاختبار التجريبي</span><h2>سكّر المذكرة.<br>وشوف وش بقي معك.</h2><p>20 سؤالًا جديدًا، من دون تلميحات أثناء الاختبار.<br>بعد التسليم، ترجع للأفكار اللي تحتاج مراجعة.</p><div class="nb-final-actions">'+link('/mock-exam/',P.draft?'أكمل اختبارك':'اختبر نفسك','button secondary')+link('/results/',P.attempts.length?'شوف نتائجك السابقة':'عن النتيجة وخطة المراجعة','nb-quiet-link')+'</div></div><figure class="nb-source"><div class="nb-source-paper">'+image('/reference/cover.webp','غلاف مذكرة تقن 107 — إعداد إبراهيم علي')+'</div><figcaption><span>المذكرة الأصلية</span><button data-act="open-booklet" class="nb-quiet-link">افتح المرجع ↗</button></figcaption></figure></section></div>';};
catalogView=function(){return '<div class="nb-width nb-catalog"><header class="page-heading"><span class="eyebrow">الفهرس / تقن 107</span><h1>خذها فكرة، فكرة.</h1><p>6 وحدات. ابدأ بالترتيب، أو ارجع للي تحتاجه.</p></header>'+notebookContinue()+notebookIndex()+'<div class="nb-catalog-bottom"><span>جاهز للتطبيق؟</span>'+link('/exam/','انتقل إلى أسئلة الامتحان','nb-quiet-link')+'</div></div>';};
const renderBeforeNotebook=render;
render=function(keep=false){renderBeforeNotebook(keep);if(path==='/')return;const page=$('#main .ed-page');if(!page)return;const l=path.startsWith('/learn/')?lessons.find(x=>x.id===path.split('/')[2]):null,label=l?l.title:path.startsWith('/learn')?'الفهرس':path.startsWith('/exam')?'ورقة الأسئلة':path.startsWith('/mock-exam')?'اختبر نفسك':'النتائج';const crumbs=document.createElement('nav');crumbs.className='nb-crumbs nb-width';crumbs.setAttribute('aria-label','مسار الصفحة');crumbs.innerHTML='<a href="#/">تقن 107</a><span aria-hidden="true">/</span>'+(l?'<a href="#/learn/">الفهرس</a><span aria-hidden="true">/</span>':'')+'<span aria-current="page">'+esc(label)+'</span>';page.prepend(crumbs);
if(l){const main=$('.lesson-main'),index=lessons.indexOf(l),eyebrow=$('.page-heading .eyebrow',main),desc=$('.page-heading>p',main);if(eyebrow)eyebrow.textContent='الوحدة 0'+(index+1)+' / '+l.minutes+' دقائق';if(desc)desc.textContent={types:'اختَر نوع القيمة، وشوف ليش.',operations:'غيّر العملية. وش صار في الناتج؟',flowcharts:'افهم الشكل، ثم رتّب خطوات الحل.',conditions:'غيّر القيمة، وتابع المسار.',loops:'ثلاث قيم، وثلاث دورات. تابع ما يتغيّر في كل مرة.',functions:'اختر دالة، وجرّب أثرها.'}[l.id];const title=$('.lesson-sidebar .sidebar-title');if(title)title.textContent='في هذه المذكرة';const picker=document.createElement('label');picker.className='nb-mobile-courses';picker.innerHTML='<span>الوحدة</span><select data-notebook="lesson-route" aria-label="اختر وحدة المراجعة">'+lessons.map((x,i)=>'<option value="'+x.id+'" '+(x.id===l.id?'selected':'')+'>'+String(i+1).padStart(2,'0')+' / '+x.title+(P.completed.includes(x.id)?' ✓':'')+'</option>').join('')+'</select>';main.prepend(picker);}
};
document.addEventListener('change',e=>{if(e.target.dataset.notebook==='lesson-route')navigate('/learn/'+e.target.value+'/');});
document.addEventListener('click',e=>{if(e.target.closest?.('[data-notebook="about"]'))dialog('عن مذكرة تقن 107','إعداد إبراهيم علي · مملكة البحرين','<div class="nb-about"><p>المراجعة مبنية على مذكرة تقن وأسئلة الامتحان المرفق. الاختبار التجريبي تدريب مستقل، وليست أسئلته امتحانًا رسميًا.</p><p>الخط والمراجع والأنشطة مضمّنة في الملف. يُحفظ تقدّمك في هذا المتصفح على هذا الجهاز؛ حذف بياناته قد يحذف التقدّم.</p><p>هذه نسخة للتعلّم وليست اختبارًا محميًا؛ مفاتيح الإجابات موجودة داخل الملف.</p><div class="actions">'+button('open-booklet','افتح المذكرة')+button('close-dialog','إغلاق','','button secondary')+'</div></div>');});


// Explicit answer states, contextual corrections and accessible confirmations.
feedback=function(ok,text){return '<div class="feedback '+(ok?'success':'error')+'" role="status" aria-live="polite" aria-atomic="true"><span class="nb-feedback-symbol" aria-hidden="true">'+(ok?'✓':'✕')+'</span><div><strong>'+(ok?'الحل صحيح':'الحل يحتاج مراجعة')+'</strong><p>'+text+'</p></div></div>';};
const questionBeforeNotebook=question;
question=function(q){const host=document.createElement('div');host.innerHTML=questionBeforeNotebook(q);const selected=UI.answers[q.id]||'',checked=!!UI.checked[q.id],ok=correct(q,selected),panel=host.firstElementChild;
 const actions=panel.querySelector('.actions');if(!checked){const status=document.createElement('p');status.className='nb-answer-instruction';status.textContent=selected.trim()?(q.options?'هذا اختيارك فقط. اضغط «تحقّق من الإجابة».':'إجابتك جاهزة. اضغط «تحقّق من الإجابة».'):q.options?'اختر إجابة لتفعيل التحقّق.':'اكتب الناتج لتفعيل التحقّق.';actions.before(status);}
 if(checked){const fb=panel.querySelector('.feedback');fb.id='nb-feedback-'+q.id;fb.querySelector('strong').textContent=ok?'إجابة صحيحة':'إجابة غير صحيحة';panel.querySelectorAll('.answer-option').forEach(b=>{const right=b.dataset.option===q.answer,chosen=b.dataset.option===selected;b.classList.toggle('nb-choice-incorrect',chosen&&!right);b.classList.toggle('nb-choice-correct',right);b.querySelectorAll(':scope > span[aria-hidden]').forEach(n=>n.remove());if(right||chosen){const label=document.createElement('span');label.className='nb-answer-state';label.textContent=right?'✓ الإجابة الصحيحة':'✕ إجابتك';b.appendChild(label);}});const input=panel.querySelector('textarea');if(input){input.setAttribute('aria-invalid',String(!ok));input.setAttribute('aria-describedby',fb.id);input.classList.add(ok?'nb-input-correct':'nb-input-incorrect');}const check=actions.querySelector('[data-act="check-question"]');if(check)check.remove();const retry=actions.querySelector('[data-act="retry-question"]');if(retry){retry.textContent=ok?'أعد السؤال':'جرّب مرة ثانية';retry.className=ok?'text-button':'button';}panel.appendChild(actions);}
 return host.innerHTML;};
dialog=function(title,description,body){if(title==='خريطة الأسئلة')description='اختر رقم السؤال للانتقال إليه. يمكنك مراجعة اختياراتك وتعديلها قبل التسليم.';const d=$('#dialog');if(!d.open)focusBeforeDialog=document.activeElement;const temporary=document.createElement('div');temporary.innerHTML=body;const danger=!!temporary.querySelector('[data-act="confirm-reset"]'),warning=!!temporary.querySelector('[data-act="confirm-restart"],[data-act="confirm-targeted"]'),submit=!!temporary.querySelector('[data-act="confirm-submit"]'),map=!!temporary.querySelector('[data-act="mock-index"]'),source=!!temporary.querySelector('.px-source-panel');d.dataset.tone=danger?'danger':warning?'warning':submit?'submit':map?'map':source?'source':'info';d.setAttribute('aria-describedby','dialog-description');d.innerHTML='<button class="modal-close" data-act="close-dialog" aria-label="إغلاق النافذة">×</button><div class="nb-dialog-heading"><span class="nb-dialog-label">'+(danger?'إدارة التقدّم':warning?'قبل المتابعة':submit?'الخطوة الأخيرة':map?'التنقّل بين الأسئلة':source?'المصدر الأصلي':'تقن 107')+'</span><h2 id="dialog-title">'+esc(title)+'</h2><p id="dialog-description">'+esc(description)+'</p></div><div class="nb-dialog-body">'+body+'</div>';if(!d.open)d.showModal();requestAnimationFrame(()=>{if(!d.open)return;const cancel=(danger||warning||submit||source)?d.querySelector('.nb-dialog-body [data-act="close-dialog"]'):null;const titleNode=d.querySelector('#dialog-title');if(cancel)cancel.focus({preventScroll:true});else{titleNode.tabIndex=-1;titleNode.focus({preventScroll:true});}});};
submitDialog=function(){const d=P.draft;if(!d)return;const qs=draftQuestions(),answered=qs.filter(q=>String(d.answers[q.id]||'').trim()).length,missing=qs.length-answered,flagged=qs.filter(q=>d.flags.includes(q.id)).length;const pending=qs.map((q,i)=>({q,i})).filter(({q})=>!String(d.answers[q.id]||'').trim());dialog('نراجع المحاولة، ثم نسلّم؟','بعد تأكيد التسليم تُحفظ النتيجة وتظهر الحلول. لا يمكن تعديل إجابات هذه المحاولة بعد تسليمها.','<div class="submission-counts"><div><strong>'+answered+'</strong><span>تمت الإجابة</span></div><div><strong>'+missing+'</strong><span>دون إجابة</span></div><div><strong>'+flagged+'</strong><span>للمراجعة ⚑</span></div></div>'+(missing?'<div class="nb-dialog-notice"><strong>'+(missing===1?'باقي سؤال واحد دون إجابة.':missing===2?'باقي سؤالان دون إجابة.':'باقي '+missing+(missing<=10?' أسئلة':' سؤالًا')+' دون إجابة.')+'</strong><p>يمكنك الرجوع لها الآن. السؤال المتروك يُحتسب بصفر.</p><details class="nb-pending-disclosure"><summary>انتقل إلى سؤال لم تجب عنه <span aria-hidden="true">+</span></summary><div class="nb-pending-questions" aria-label="الأسئلة غير المجاب عنها">'+pending.map(({i})=>button('mock-index',String(i+1),'data-index="'+i+'" aria-label="الرجوع إلى السؤال '+(i+1)+'"','nb-pending-question')).join('')+'</div></details></div>':'<p class="nb-all-answered">✓ أجبت عن جميع الأسئلة. راجع العلامات إن احتجت، ثم سلّم محاولتك.</p>')+'<div class="actions nb-dialog-actions">'+button('confirm-submit','تأكيد التسليم')+button('close-dialog','أرجع للمراجعة','','button secondary')+'</div>');};
const toastNode=$('#toast');let toastReturnFocus=null;
toast=function(message){clearTimeout(toastTimer);toastReturnFocus=document.activeElement;const error=/تعذّر|غير متاح/.test(message),success=/تم نسخ|تمت إعادة ضبط/.test(message);toastNode.dataset.tone=error?'error':success?'success':'info';toastNode.setAttribute('role','status');toastNode.setAttribute('aria-live','polite');toastNode.setAttribute('aria-atomic','true');toastNode.innerHTML='<span class="nb-toast-mark" aria-hidden="true">'+(error?'!':success?'✓':'i')+'</span><span>'+esc(message)+'</span><button data-notebook="dismiss-toast" aria-label="إغلاق التنبيه">×</button>';toastNode.hidden=false;if(!error)toastTimer=setTimeout(()=>toastNode.hidden=true,5000);};
toastNode.addEventListener('mouseenter',()=>clearTimeout(toastTimer));toastNode.addEventListener('focusin',()=>clearTimeout(toastTimer));toastNode.addEventListener('mouseleave',()=>{if(!toastNode.contains(document.activeElement))toastTimer=setTimeout(()=>toastNode.hidden=true,4000);});toastNode.addEventListener('focusout',()=>{toastTimer=setTimeout(()=>toastNode.hidden=true,4000);});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
document.addEventListener('click',e=>{if(e.target.closest?.('[data-notebook="dismiss-toast"]')){clearTimeout(toastTimer);toastNode.hidden=true;if(toastReturnFocus?.isConnected)toastReturnFocus.focus({preventScroll:true});}});
function notebookFieldResult(key,ok){const field=document.querySelector('[data-bind="'+CSS.escape(key)+'"]');if(!field)return;field.setAttribute('aria-invalid',String(!ok));field.classList.add(ok?'nb-input-correct':'nb-input-incorrect');const note=document.createElement('small');note.id='nb-field-'+key.replace(/[^a-z0-9]/gi,'-');note.className='nb-field-state '+(ok?'is-correct':'is-incorrect');note.textContent=ok?'✓ صحيح':'✕ راجع القيمة';field.setAttribute('aria-describedby',note.id);if(field.closest('.completion-code')){const wrap=document.createElement('span');wrap.className='nb-blank-wrap';field.before(wrap);wrap.appendChild(field);note.classList.add('nb-inline-field-state');note.innerHTML='<span aria-hidden="true">'+(ok?'✓':'✕')+'</span><span class="nb-screen-reader">'+(ok?'إجابة صحيحة':'راجع القيمة')+'</span>';wrap.appendChild(note);}else field.after(note);}
const renderBeforeAnswerStates=render;
render=function(keep=false){renderBeforeAnswerStates(keep);
 if(path.startsWith('/mock-exam')&&P.draft){const d=P.draft,q=draftQuestions()[d.index],section=$('.assessment-question');if(section){const status=document.createElement('p');status.className='nb-draft-status';status.setAttribute('role','status');status.textContent=d.answers[q.id]?(storageError?'الإجابة محدّدة، لكن الحفظ غير متاح في هذا المتصفح.':'اختيارك محفوظ. يمكنك تغييره قبل التسليم.'):'اختر إجابتك، ثم انتقل إلى السؤال التالي.';section.querySelector('.answer-options')?.after(status);}return;}
 if(path.startsWith('/learn/types')&&UI.miniType){const q=typeExamples[UI.typeQuiz];document.querySelectorAll('[data-act="mini-type"]').forEach(b=>{const right=b.dataset.type===q.type,chosen=b.dataset.type===UI.miniType;b.classList.toggle('nb-choice-correct',right);b.classList.toggle('nb-choice-incorrect',chosen&&!right);if(right||chosen){const mark=document.createElement('span');mark.className='nb-mini-mark';mark.setAttribute('aria-hidden','true');mark.textContent=right?'✓':'✕';b.appendChild(mark);b.setAttribute('aria-label',b.dataset.type+(right?'، النوع الصحيح':'، إجابتك غير صحيحة'));}});const fb=$('.lesson-tool .feedback');if(fb)fb.querySelector('strong').textContent=UI.miniType===q.type?'إجابة صحيحة':'إجابة غير صحيحة';}
 if(path.startsWith('/learn/flowcharts')&&UI.builderChecked){const bad=UI.slots.map((x,i)=>x===blocks[i][0]?-1:i+1).filter(i=>i>0);document.querySelectorAll('[data-act="place-block"]').forEach((b,i)=>{b.setAttribute('aria-label','الخانة '+(i+1)+': '+(bad.includes(i+1)?'تحتاج مراجعة':'صحيحة'));const state=document.createElement('span');state.className='nb-slot-status';state.textContent=bad.includes(i+1)?'✕':'✓';state.setAttribute('aria-hidden','true');b.appendChild(state);});const fb=$('.ux-reference .feedback');if(fb&&bad.length){const detail=document.createElement('p');detail.textContent='راجع الخانات: '+bad.join('، ')+'.';fb.querySelector('div').appendChild(detail);}}
 if(path.startsWith('/exam')){if(UI.checked['original-1']){notebookFieldResult('q1.list',validList(v('q1.list')));for(const [key,expected]of [['q1.sum','sum(Ltest)'],['q1.condition','sm < 100'],['q1.branch','Yes']])notebookFieldResult(key,v(key)===expected);}if(UI.checked['original-3']){traceRows.forEach((r,i)=>['i','x','y'].forEach(k=>notebookFieldResult('q3.'+i+'.'+k,String(v('q3.'+i+'.'+k))===String(r[k]))));notebookFieldResult('q3.z',v('q3.z')==='35');}if(UI.checked['original-5'])completion.forEach(([key,value])=>notebookFieldResult('q5.'+key,String(v('q5.'+key)).trim()===value));document.querySelectorAll('[data-act="check-original"][disabled]').forEach(b=>{if(UI.checked[b.dataset.group])return;const note=document.createElement('p');note.className='nb-answer-instruction';note.textContent='أكمل الحقول المطلوبة لتفعيل التحقّق.';b.closest('.actions').after(note);});}
};


// Keep deep links and the saved resume location aligned with explicit question/function navigation.
