document.addEventListener('click',e=>{const button=e.target.closest?.('[data-act]');if(!button||button.disabled)return;if(path.startsWith('/exam')&&['exam-tab','exam-next','exam-prev'].includes(button.dataset.act))notebookRememberLocation('/exam/?q='+(UI.exam+1));});
document.addEventListener('change',e=>{if(e.target.dataset.ux==='function-select'&&path.startsWith('/learn/functions/'))notebookRememberLocation('/learn/functions/?function='+encodeURIComponent(funcs[UI.function].name.replace(/\(\)$/,'')));});


// Durable learning experience: lesson positions, complete workspace, disclosures and resume location.
const EXPERIENCE_KEY='tgn107.experience.v2';
const experienceDefaults={values:{},answers:{},checked:{},types:0,typeQuiz:0,miniType:'',operator:'/',shape:'start',slots:['','','','',''],block:'',builderChecked:false,sm:75,comparison:'<',function:0,ran:false,step:0,playing:false,exam:0,flowStep:0,filter:'all',review:false,attemptId:'',outputPart:0,errorPart:0,reviewFilter:'wrong',stage:0};
function experienceFresh(){return {version:2,ui:{},lessons:{},views:{},route:'/',lastLearning:'',updatedAt:0};}
let experience=experienceFresh(),experienceRenderedScope='',experienceRestoring=false,experienceResetting=false,experienceSaveTimer=0,experienceScrollFrame=0;
function experienceRoute(value){if(typeof value!=='string'||value.length>220||/[<>"'\\\s]/.test(value))return '';const base=value.split('?')[0];return /^(?:\/|\/learn\/?|\/learn\/(?:types|operations|flowcharts|conditions|functions)\/?|\/exam\/?|\/mock-exam\/?|\/results\/?)$/.test(base)?value:'';}
function experienceLessonId(){return path.startsWith('/learn/')&&lessons.some(l=>l.id===path.split('/')[2])?path.split('/')[2]:'';}
try{const saved=JSON.parse(localStorage.getItem(EXPERIENCE_KEY)||'null');if(saved&&saved.version===2){experience.route=experienceRoute(saved.route)||'/';experience.lastLearning=experienceRoute(saved.lastLearning)||'';for(const id of lessons.map(l=>l.id)){const entry=saved.lessons?.[id];if(entry&&typeof entry==='object')experience.lessons[id]={visited:!!entry.visited,step:entry.step===1?1:0,updatedAt:Number(entry.updatedAt)||0};}if(saved.views&&typeof saved.views==='object'&&!Array.isArray(saved.views))for(const [key,view]of Object.entries(saved.views).slice(-300)){if(view&&typeof view==='object')experience.views[key]={scroll:Math.max(0,Number(view.scroll)||0),details:view.details&&typeof view.details==='object'?view.details:{}};}
const allowed=new Set([...Object.keys(experienceDefaults),...Object.keys(UI)]);if(saved.ui&&typeof saved.ui==='object')for(const [key,value]of Object.entries(saved.ui)){if(!allowed.has(key)||key==='playing'||key==='focusRequested')continue;if(['values','answers','checked'].includes(key)){if(value&&typeof value==='object'&&!Array.isArray(value)){const record={};for(const [field,v]of Object.entries(value)){if(field==='__proto__'||field==='constructor'||field==='prototype')continue;if(key==='checked'&&typeof v==='boolean'||key==='answers'&&typeof v==='string'||key==='values'&&['string','number','boolean'].includes(typeof v))record[field]=v;}UI[key]=record;}}else if(key==='slots'){if(Array.isArray(value)&&value.length===5)UI.slots=value.map(v=>blocks.some(b=>b[0]===v)?v:'');}else if(['string','number','boolean'].includes(typeof value))UI[key]=value;}
const clamp=(key,max)=>UI[key]=Math.max(0,Math.min(max,Math.floor(Number(UI[key])||0)));clamp('types',typeExamples.length-1);clamp('typeQuiz',typeExamples.length-1);clamp('function',funcs.length-1);clamp('exam',5);clamp('outputPart',originalOutputs.length-1);clamp('errorPart',errorExamples.length-1);clamp('step',loopStates.length-1);clamp('flowStep',4);clamp('stage',2);UI.sm=Math.max(0,Math.min(150,Number(UI.sm)||0));if(!shapeData.some(x=>x[0]===UI.shape))UI.shape='start';if(!['/','//','%','+','-','*'].includes(UI.operator))UI.operator='/';if(!['<','>','==','!=','<=','>='].includes(UI.comparison))UI.comparison='<';if(!typeExamples.some(x=>x.type===UI.miniType))UI.miniType='';UI.playing=false;UI.focusRequested='';
if(!location.hash.startsWith('#/')&&experience.route!=='/'){try{history.replaceState(null,'','#'+experience.route);path=experience.route;}catch{}}if(experience.route===path){lastRenderedPath=path;const id=experienceLessonId();if(id){P.currentLesson=id;UX.step=experience.lessons[id]?.step??UX.step;UX.route=path;}}if(experience.lastLearning)UX.lastContext=experience.lastLearning;
}}catch{}
const legacyLesson=lessons.find(l=>UX.lastContext&&UX.lastContext.split('?')[0]==='/learn/'+l.id+'/');if(legacyLesson&&!experience.lessons[legacyLesson.id])experience.lessons[legacyLesson.id]={visited:true,step:UX.step===1?1:0,updatedAt:Date.now()};
function experienceMarkLesson(){const id=experienceLessonId();if(!id||experienceResetting)return;experience.lessons[id]={visited:true,step:UX.step===1?1:0,updatedAt:Date.now()};}
function experienceScope(){const id=experienceLessonId();if(id)return 'lesson:'+id+':'+UX.step+(id==='functions'?':'+UI.function:'');if(path.startsWith('/exam'))return 'exam:'+UI.exam+':'+(UI.outputPart||0)+':'+(UI.errorPart||0);if(path.startsWith('/mock-exam'))return P.draft?'mock:'+P.draft.startedAt+':'+P.draft.index:'mock:intro';if(path.startsWith('/results'))return 'results:'+(selectedAttempt()?.id||'none')+':'+!!UI.review+':'+(UI.reviewFilter||'wrong');return path.startsWith('/learn')?'catalog':'home';}
function experienceDetails(){const result={};document.querySelectorAll('#main details').forEach((d,i)=>result[d.id||'detail-'+i]=d.open);return result;}
function experienceCaptureView(scope=experienceRenderedScope){if(!scope)return;experience.views[scope]={scroll:Math.max(0,scrollY),details:experienceDetails()};}
function experiencePersist(capture=true){clearTimeout(experienceSaveTimer);if(capture&&!experienceRestoring)experienceCaptureView();experienceMarkLesson();experience.ui={};for(const [key,value]of Object.entries(UI))if(!['playing','focusRequested'].includes(key))experience.ui[key]=value;experience.ui.playing=false;experience.route=experienceResetting?'/':experienceRoute(path)||'/';experience.lastLearning=experienceResetting?'':experienceRoute(UX.lastContext)||experience.lastLearning;experience.updatedAt=Date.now();try{writeVerified(EXPERIENCE_KEY,JSON.stringify(experience));}catch{storageError=true;}const warning=$('#storage-alert');if(warning)warning.hidden=!storageError;}
function experienceLessonStatus(id){const completed=P.completed.includes(id),entry=experience.lessons[id],check=lessonChecks[id],answered=String(UI.answers[check.id]||'').trim(),legacy=P.practice.some(a=>a.questionId===check.id||id==='types'&&a.questionId.startsWith('type-mini-')||id==='flowcharts'&&a.questionId==='flow-builder'||id==='functions'&&a.questionId.startsWith('function-')),passed=!!UI.checked[check.id]&&correct(check,UI.answers[check.id]);const visited=completed||!!entry?.visited||!!answered||legacy;const step=completed?3:visited?entry?.step===1||answered?2:1:0;return {completed,visited,passed,step,percent:completed?100:step===2?67:step===1?33:0,label:completed?'مكتمل':passed?'جاهز للإكمال':visited?'قيد المراجعة':'لم يبدأ',detail:completed?'اجتزت سؤال الفهم':!visited?'ابدأ متى ما يناسبك':passed?'باقي تأكيد إكمال الوحدة':step===2?'الخطوة 2 من 3 · سؤال الفهم':'الخطوة 1 من 3 · جرّب الفكرة'};}
function experienceTrack(percent,label,extra=''){return '<div class="pm-track '+extra+'" role="progressbar" aria-label="'+esc(label)+'" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+percent+'"><span style="width:'+percent+'%"></span></div>';}
notebookIndex=function(){const examples=['42 · True · "Ali"','9 / 2 · 9 // 2','بداية ← قرار ← نهاية','if / else','for i in range(...)','len() · pop() · range()'];return '<div class="nb-index-list pm-index">'+lessons.map((l,i)=>{const state=experienceLessonStatus(l.id),kind=state.completed?'complete':state.visited?'started':'new';return '<a class="nb-index-row pm-row is-'+kind+'" href="#/learn/'+l.id+'/" aria-label="'+esc(l.title+'، '+state.label+'، '+state.detail)+'"><span class="nb-index-no" dir="ltr">0'+(i+1)+'</span><span class="nb-index-name">'+l.title+'<small>'+esc(l.description)+'</small></span><code class="nb-index-example" dir="ltr">'+esc(examples[i])+'</code><span class="pm-index-status"><strong><i aria-hidden="true"></i>'+state.label+'</strong><small>'+state.detail+'</small>'+experienceTrack(state.percent,'خطوات '+l.title)+'</span><span class="pm-state-icon" aria-hidden="true">'+(state.completed?'✓':state.visited?'◐':'←')+'</span></a>';}).join('')+'</div>';};
const lessonBeforeExperience=lessonView;
lessonView=function(id){if(lessons.some(l=>l.id===id)){if(UX.route!==path){const params=new URLSearchParams(path.split('?')[1]||'');UX.step=params.has('function')||params.get('focus')==='loops'?0:experience.lessons[id]?.step??0;UX.route=path;}experienceMarkLesson();}return lessonBeforeExperience(id);};
function experienceLessonBar(id){const status=experienceLessonStatus(id),current=UX.step===1?1:0;return '<section class="pm-lesson-position '+(status.completed?'is-complete':'is-started')+'" aria-label="موقعك في الدرس"><div class="pm-position-top"><div><span class="pm-position-caption">موقعك في خطوات الدرس</span><strong>'+status.label+'</strong></div><span class="pm-save-state">'+(storageError?'! الحفظ غير متاح':'✓ محفوظ تلقائيًا')+'</span></div>'+experienceTrack(status.percent,'خطوات الوحدة: '+status.detail)+'<ol class="pm-milestones"><li class="'+(status.completed?'done':current===0?'current':'done')+'" '+(current===0?'aria-current="step"':'')+'><span aria-hidden="true">'+(status.completed||current===1?'✓':'1')+'</span><b>جرّب الفكرة</b></li><li class="'+(status.completed?'done':current===1?'current':'')+'" '+(current===1?'aria-current="step"':'')+'><span aria-hidden="true">'+(status.completed?'✓':'2')+'</span><b>تأكّد من فهمك</b></li><li class="'+(status.completed?'done':status.passed?'ready':'')+'"><span aria-hidden="true">'+(status.completed?'✓':'3')+'</span><b>'+(status.completed?'الوحدة مكتملة':status.passed?'أكمل الوحدة':'ثبّت تعلّمك')+'</b></li></ol><p class="pm-step-guidance">'+(status.completed?'الوحدة مكتملة ومحفوظة. تقدر ترجع لأي خطوة للمراجعة.':status.passed?'اجتزت السؤال. اضغط «أكملت الدرس» لتثبيت الإكمال والانتقال للوحدة التالية.':current===1?'جاوب عن سؤال الفهم. الإكمال يتثبّت بعد الإجابة الصحيحة وتأكيدك.':'جرّب الفكرة أولًا، ثم انتقل إلى سؤال الفهم.')+'</p></section>';}
function experienceOverall(){const p=getLearningProgress();return '<div class="pm-overall"><div><strong>'+p.completed+' من '+p.total+' وحدات مكتملة</strong><span>'+p.percentage+'%</span></div>'+experienceTrack(p.percentage,'الوحدات المكتملة')+'<div class="pm-legend"><span><i class="legend-complete"></i>مكتمل</span><span><i class="legend-started"></i>قيد المراجعة</span><span><i></i>لم يبدأ</span></div></div>';}
const renderBeforeExperience=render;
render=function(keep=false){const previous=experienceRenderedScope;if(previous)experienceCaptureView(previous);if(experienceResetting&&path==='/')experienceResetting=false;renderBeforeExperience(keep);experienceMarkLesson();const id=experienceLessonId();if(id){const main=$('.lesson-main'),heading=$('.page-heading',main);heading.insertAdjacentHTML('afterend',experienceLessonBar(id));document.querySelectorAll('.sidebar-lesson').forEach(a=>{const l=lessons.find(l=>a.hash.includes('/'+l.id+'/'));if(!l)return;const state=experienceLessonStatus(l.id);a.classList.add('pm-sidebar',state.completed?'is-complete':state.visited?'is-started':'is-new');a.setAttribute('aria-label',l.title+'، '+state.label);const marker=a.querySelector('span');if(marker)marker.textContent=state.completed?'✓':state.visited?'◐':String(lessons.indexOf(l)+1);a.insertAdjacentHTML('beforeend','<small class="pm-sidebar-state">'+state.label+'</small>');});const complete=$('.lesson-complete');if(complete&&P.completed.includes(id)){complete.classList.add('pm-completion-confirmed');complete.querySelector('h3').textContent='✓ الوحدة مكتملة ومحفوظة';}if(complete&&!P.completed.includes(id)&&experienceLessonStatus(id).passed){complete.classList.add('pm-ready-to-complete');complete.querySelector('h3').textContent='اجتزت السؤال. باقي تثبيت الإكمال.';complete.querySelector('p').textContent='اضغط «أكملت الدرس» ليصير تقدّم هذه الوحدة مكتملًا.';}}
document.querySelectorAll('.nb-contents-heading,.nb-catalog>.page-heading').forEach(el=>el.insertAdjacentHTML('beforeend',experienceOverall()));const scope=experienceScope(),view=experience.views[scope],changed=scope!==previous;experienceRenderedScope=scope;experienceRestoring=true;let helped=false;document.querySelectorAll('#main details').forEach((d,i)=>{const key=d.id||'detail-'+i;const local=viewportTransaction?.preserve?viewportTransaction.details:null;if(local&&Object.prototype.hasOwnProperty.call(local,key)||view){let open=local&&Object.prototype.hasOwnProperty.call(local,key)?!!local[key]:!!view.details[key];if(d.classList.contains('ux-help')&&open){if(helped)open=false;else helped=true;}d.open=open;}else if(changed&&!viewportTransaction?.preserve)d.open=false;});experienceRestoring=false;experiencePersist(false);if(changed&&view&&!viewportTransaction?.preserve){const restoreEpoch=viewportEpoch;requestAnimationFrame(()=>{if(experienceRenderedScope!==scope||restoreEpoch!==viewportEpoch)return;const max=Math.max(0,document.documentElement.scrollHeight-innerHeight);scrollTo({top:Math.min(view.scroll,max),behavior:'instant'});experienceUpdateReading();});}else experienceUpdateReading();};
function experienceUpdateReading(){const id=experienceLessonId(),header=$('#navigation');let line=$('#pm-reading-line');if(!line){line=document.createElement('div');line.id='pm-reading-line';line.className='pm-reading-line';line.innerHTML='<span></span>';line.setAttribute('role','progressbar');line.setAttribute('aria-label','موضعك في صفحة الدرس، وليس نسبة الإكمال');line.setAttribute('aria-valuemin','0');line.setAttribute('aria-valuemax','100');header.appendChild(line);}line.hidden=!id;if(!id)return;const main=$('.lesson-main');if(!main)return;const start=main.getBoundingClientRect().top+scrollY-header.offsetHeight,extent=Math.max(1,main.scrollHeight-(innerHeight-header.offsetHeight));const percentage=Math.max(0,Math.min(100,Math.round((scrollY-start)/extent*100)));line.setAttribute('aria-valuenow',String(percentage));line.firstElementChild.style.width=percentage+'%';}
document.addEventListener('input',e=>{if(e.target.matches('input,select,textarea'))experiencePersist();});document.addEventListener('change',e=>{if(e.target.matches('input,select,textarea'))experiencePersist();});
document.addEventListener('click',e=>{const target=e.target.closest?.('[data-act],[data-ux],[data-notebook]');if(target)experiencePersist();});
document.addEventListener('toggle',e=>{if(e.target.matches?.('#main details')&&!experienceRestoring){clearTimeout(experienceSaveTimer);markPersistencePending(EXPERIENCE_KEY);experienceSaveTimer=setTimeout(()=>experiencePersist(),0);}},true);
addEventListener('scroll',()=>{cancelAnimationFrame(experienceScrollFrame);experienceScrollFrame=requestAnimationFrame(experienceUpdateReading);clearTimeout(experienceSaveTimer);markPersistencePending(EXPERIENCE_KEY);experienceSaveTimer=setTimeout(()=>experiencePersist(),180);},{passive:true});addEventListener('resize',experienceUpdateReading);addEventListener('pagehide',()=>experiencePersist());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')experiencePersist();});
