notebookContinue=function(){const started=Object.values(experience.lessons).some(l=>l.visited);if(!started&&!getLearningProgress().completed&&!P.practice.length&&!P.draft)return '';const route=P.draft?'/mock-exam/':UX.lastContext&&experienceRoute(UX.lastContext)?UX.lastContext:'/learn/'+P.currentLesson+'/';const lesson=lessons.find(l=>route.split('?')[0]==='/learn/'+l.id+'/'),state=lesson?experienceLessonStatus(lesson.id):null;const detail=P.draft?'اختبارك الجاري وإجاباتك محفوظة.':lesson?lesson.title+' · '+(state.completed?'مكتمل':state.detail):getLearningProgress().completed+' من '+lessons.length+' وحدات مكتملة.';return '<a class="nb-continue" href="#'+esc(route)+'"><span class="nb-continue-dot" aria-hidden="true"></span><span><strong>نكمل من آخر مرة؟</strong><small>'+esc(detail)+'</small></span><span aria-hidden="true">←</span></a>';};


// Clear persistent choices, cinematic TGN cover and a student-only answer overview.
const homeBeforeClarity=homeView;
homeView=function(){const host=document.createElement('div');host.innerHTML=homeBeforeClarity();const oldCover=host.querySelector('.nb-cover');if(!oldCover)return host.innerHTML;const scratch=oldCover.querySelector('.nb-scratch');const section=document.createElement('section');section.className='nx-hero';section.id='hero';section.innerHTML='<div class="nx-hero-picture" aria-hidden="true"></div><div class="nx-hero-content nb-width"><div class="nx-hero-copy"><span class="nx-eyebrow"><i aria-hidden="true"></i>تقن 107 · مراجعة البايثون</span><h1>افهم الفكرة.<br><span>واختبر نفسك بثقة.</span></h1><p>مراجعة تجمع الأساسيات، وأسئلة الامتحان، واختبارًا تعرف فيه مستواك. كل خطوة واضحة، وتقدّمك يبقى معك.</p><div class="nx-hero-actions"><a class="nx-action nx-action-gold" href="#/learn/'+P.currentLesson+'/"><span>ابدأ المراجعة</span><i aria-hidden="true">←</i></a><a class="nx-action nx-action-dark" href="#journey"><span>استكشف المحتوى</span><i aria-hidden="true">↓</i></a></div>'+notebookContinue()+'</div></div><div class="nx-hero-foot nb-width"><a href="#journey">خذها فكرة، فكرة <span aria-hidden="true">↓</span></a><span>'+getLearningProgress().completed+' من '+lessons.length+' وحدات مكتملة</span><span>تعلّم على راحتك. تقدّمك محفوظ.</span></div>';oldCover.replaceWith(section);if(scratch){const trial=document.createElement('section');trial.className='nx-try-section nb-width';trial.innerHTML='<div class="nx-try-copy"><span class="nb-section-label">جرّب قبل ما تبدأ</span><h2>علامة صغيرة.<br>نتيجة مختلفة.</h2><p>نفس الرقمين، بثلاث عمليات. غيّر العلامة وشوف كيف يتغيّر الناتج.</p><a class="nb-quiet-link" href="#/learn/operations/">افهم العمليات بالتجربة <span aria-hidden="true">←</span></a></div>';trial.appendChild(scratch);const index=host.querySelector('.nb-contents');index.after(trial);}return host.innerHTML;};
const mockBeforeClarity=mockView;
mockView=function(){const host=document.createElement('div');host.innerHTML=mockBeforeClarity();if(!P.draft)return host.innerHTML;const qs=draftQuestions(),q=qs[P.draft.index],answer=P.draft.answers[q.id],group=host.querySelector('.assessment-question .answer-options');if(!group)return host.innerHTML;group.setAttribute('role','radiogroup');group.setAttribute('aria-label','اختر إجابة واحدة، ويمكنك تغييرها قبل التسليم');group.querySelectorAll('[data-act="mock-answer"]').forEach((option,i)=>{const chosen=option.dataset.option===answer;const text=option.querySelector('bdi');if(text)text.setAttribute('dir',/[\u0600-\u06ff]/.test(option.dataset.option)?'auto':'ltr');option.classList.toggle('nx-student-selected',chosen);option.setAttribute('role','radio');option.removeAttribute('aria-pressed');option.setAttribute('aria-checked',String(chosen));option.setAttribute('tabindex',chosen||!answer&&i===0?'0':'-1');option.setAttribute('aria-label',String.fromCharCode(65+i)+': '+option.dataset.option+(chosen?'، اختيارك الحالي':''));option.querySelectorAll(':scope > span[aria-hidden]').forEach(el=>el.remove());const indicator=document.createElement('span');indicator.className='nx-choice-indicator';indicator.setAttribute('aria-hidden','true');indicator.textContent='';option.appendChild(indicator);if(chosen){const label=document.createElement('span');label.className='nx-choice-label';label.textContent='اختيارك';option.appendChild(label);}});if(answer){const receipt=document.createElement('div');receipt.className='nx-answer-receipt';receipt.innerHTML='<span class="nx-receipt-label">إجابتك المختارة</span><strong><span class="nx-receipt-letter">'+String.fromCharCode(65+q.options.indexOf(answer))+'</span><bdi dir="auto">'+esc(answer)+'</bdi></strong>';group.after(receipt);}return host.innerHTML;};
const mapBeforeClarity=questionMapButtons;
