// One progress language: current blue, saved green, pending gray, review amber.
function journeyAnswerCount(n){return n===0?'لم تحدّد إجابات بعد':n===1?'إجابة واحدة محفوظة':n===2?'إجابتان محفوظتان':n<=10?n+' إجابات محفوظة':n+' إجابة محفوظة';}
function journeyExamProgress(){const d=P.draft,qs=draftQuestions(),n=qs.length,current=d.index+1,answered=qs.filter(q=>String(d.answers[q.id]||'').trim()).length,flags=qs.filter(q=>d.flags.includes(q.id)).length,remaining=n-answered,percent=Math.round(answered/n*100);return '<section class="jt-exam-progress" aria-label="موقعك وتقدّمك في المحاولة"><div class="jt-progress-top"><div class="jt-current"><span>أنت عند السؤال</span><strong><bdi>'+current+'</bdi><small>من '+n+'</small></strong></div><div class="jt-saved '+(answered===n?'is-finished':'')+'"><span>'+(storageError?'إجابات محدّدة':'إجابات محفوظة')+'</span><strong><bdi>'+answered+'</bdi><small>/ '+n+'</small></strong></div><div class="jt-remaining"><span>دون إجابة</span><strong>'+remaining+'</strong></div><div class="jt-review '+(flags?'has-flags':'')+'"><span>للمراجعة ⚑</span><strong>'+flags+'</strong></div></div><div class="jt-progress-summary"><strong>'+(answered===n?'اكتملت إجاباتك. راجعها قبل التسليم.':journeyAnswerCount(answered)+'. يمكنك تعديلها.')+'</strong><span>'+percent+'% من الأسئلة</span></div><div class="jt-answer-track" role="progressbar" aria-label="الأسئلة التي لها إجابة محفوظة" aria-valuemin="0" aria-valuemax="'+n+'" aria-valuenow="'+answered+'"><span style="width:'+percent+'%"></span></div><div class="jt-question-trail" aria-hidden="true">'+qs.map((q,i)=>'<span class="'+(d.answers[q.id]?'is-answered ':'')+(i===d.index?'is-current ':'')+(d.flags.includes(q.id)?'is-flagged':'')+'">'+(i===d.index?'<i>'+(i+1)+'</i>':'')+'</span>').join('')+'</div><div class="jt-progress-bottom"><div class="jt-key"><span><i class="key-current"></i>مكانك الآن</span><span><i class="key-saved"></i>له إجابة</span><span><i></i>متبقّي</span><span><i class="key-review"></i>معلّم للمراجعة</span></div>'+button('mock-map-dialog','خريطة الأسئلة وإجاباتك','','text-button')+'</div></section>';}
const ACHIEVEMENT_KEY='tgn107.achievements.v1';
let learningAwards={version:1,earned:{},initialized:false},newLearningAwards=[],lastAwardAnnouncement="";
try{const saved=JSON.parse(localStorage.getItem(ACHIEVEMENT_KEY)||'null');if(saved?.version===1&&saved.earned&&typeof saved.earned==='object')learningAwards={version:1,earned:saved.earned,initialized:!!saved.initialized};}catch{}
function journeyMilestones(){const complete=new Set(P.completed),full=P.attempts.filter(a=>attemptQuestions(a).length===20),firstCorrect=P.practice.some(a=>a.correct);return [{id:'first-correct',title:'أول خطوة صحيحة',goal:'أجب عن نشاط تدريبي بشكل صحيح.',done:firstCorrect},{id:'first-unit',title:'وحدة مكتملة',goal:'اجتز سؤال الفهم وثبّت إكمال أول وحدة.',done:complete.size>=1},{id:'foundations',title:'أساس متين',goal:'أكمل وحدات المراجعة الست.',done:getLearningProgress().completed===lessons.length},{id:'previous-exam',title:'طبّقت على الورقة',goal:'أنهِ الأسئلة الستة في الامتحان السابق بنجاح.',done:originalStageProgress()===6},{id:'first-attempt',title:'أنهيت محاولتك',goal:'سلّم اختبارك التجريبي واطّلع على النتيجة.',done:P.attempts.length>0},{id:'readiness',title:'جاهزية قوية',goal:'حقّق 80% أو أكثر في اختبار شامل.',done:full.some(a=>score(attemptQuestions(a),a.answers).percent>=80)},{id:'improvement',title:'خطوة للأمام',goal:'ارفع نتيجتك في محاولتين شاملتين متتاليتين.',done:full.some((a,i)=>i>0&&score(attemptQuestions(a),a.answers).percent>score(attemptQuestions(full[i-1]),full[i-1].answers).percent)}];}
function journeySaveAwards(){try{writeVerified(ACHIEVEMENT_KEY,JSON.stringify(learningAwards));}catch{storageError=true;}}
function journeyUpdateAwards(){const fresh=[];for(const award of journeyMilestones())if(award.done&&!learningAwards.earned[award.id]){learningAwards.earned[award.id]={at:new Date().toISOString()};if(learningAwards.initialized)fresh.push(award.id);}learningAwards.initialized=true;journeySaveAwards();if(fresh.length)newLearningAwards=fresh;}
function journeyAwardIcon(unlocked){return '<span class="jt-award-mark '+(unlocked?'unlocked':'')+'" aria-hidden="true"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="m8 15-2 7 6-3 6 3-2-7"/><circle cx="12" cy="9" r="7"/>'+(unlocked?'<path d="m9 9 2 2 4-4"/>':'<path d="M10 9h4"/>')+'</svg></span>';}
function journeyAchievements(){if(path.split('?')[0]!=='/')return '';const awards=journeyMilestones(),earned=awards.filter(a=>learningAwards.earned[a.id]);return '<details class="jt-achievements" id="journey-achievements"><summary><span>'+journeyAwardIcon(earned.length>0)+'<span><strong>إنجازاتك في المراجعة</strong><small>'+earned.length+' من '+awards.length+' إنجازات · تُفتح مع تقدّمك</small></span></span><span class="jt-awards-open" aria-hidden="true">+</span></summary><div class="jt-awards-grid">'+awards.map(a=>{const unlocked=!!learningAwards.earned[a.id];return '<article class="jt-award '+(unlocked?'is-earned':'is-locked')+'">'+journeyAwardIcon(unlocked)+'<div><h3>'+a.title+'</h3><p>'+a.goal+'</p><span>'+(unlocked?'✓ حقّقته':'هدفك القادم')+'</span></div></article>';}).join('')+'</div></details>';}
function journeyCelebrate(){if(!newLearningAwards.length||P.draft&&path.startsWith('/mock-exam'))return '';const signature=newLearningAwards.join('|');if(signature===lastAwardAnnouncement)return '';lastAwardAnnouncement=signature;if(path.startsWith('/learn/')&&newLearningAwards.some(id=>id==='first-unit'||id==='foundations'))return '';const names=journeyMilestones().filter(a=>newLearningAwards.includes(a.id)).map(a=>a.title).join(' · ');queueMicrotask(()=>{toast('إنجاز جديد: '+names);toastNode.dataset.tone='success';});return '';}
function journeyStyleButtons(root=document){root.querySelectorAll('.nx-action-gold,#nav-start,.button:not(.secondary):not(.danger),[data-act=submit-dialog]').forEach(el=>{if(el.dataset.journeyButton)return;const label=el.textContent.replace(/[↖↗←→✓↺]+\s*$/g,'').trim();if(!label)return;el.dataset.journeyButton='true';el.classList.add('jt-capsule');const mark=el.dataset.act==='loop-play'?'▶':el.dataset.act==='complete-lesson'||el.dataset.act==='confirm-submit'?'✓':'←';el.innerHTML='<span class="jt-button-label">'+esc(label)+'</span><span class="jt-button-fill" aria-hidden="true"></span><span class="jt-button-arrow" aria-hidden="true"><span class="jt-arrow-clip"><span class="jt-arrow-row"><i>'+mark+'</i><i>'+mark+'</i></span></span></span>';});}
const renderBeforeJourney=render;
render=function(keep=false){renderBeforeJourney(keep);journeyUpdateAwards();if(path.startsWith('/mock-exam')&&P.draft){const old=$('.exam-progress-row');if(old){old.classList.add('jt-progress-host');old.innerHTML=journeyExamProgress();}const label=$('#assessment-nav-label');if(label){const d=P.draft,qs=draftQuestions(),n=qs.filter(q=>String(d.answers[q.id]||'').trim()).length;label.innerHTML='<strong>السؤال '+(d.index+1)+' من '+qs.length+'</strong><small>'+(storageError?'الحفظ غير متاح':journeyAnswerCount(n))+'</small>';}const actions=$('.assessment-mobile-actions');if(actions)actions.classList.add('jt-compact-actions');}else{let place;if(path==='/')place=$('.nb-contents');else if(/^\/learn\/?$/.test(path))place=$('.nb-catalog');else if(path.startsWith('/results'))place=$('.performance-story');else if(path.startsWith('/learn/'))place=$('.lesson-main');else if(path.startsWith('/exam'))place=$('.page-content');if(place){const wrap=document.createElement('div');wrap.className='jt-awards-area';wrap.innerHTML=journeyCelebrate()+journeyAchievements();place.appendChild(wrap);const banner=wrap.querySelector('.jt-new-award');if(banner){const feedback=Array.from(document.querySelectorAll('.lesson-tool .feedback,.question-specific .feedback')).find(e=>e.getClientRects().length);const completion=document.querySelector('.lesson-complete');const result=document.querySelector('.result-hero');if(path.startsWith('/learn/')&&UX.step===0&&feedback)feedback.after(banner);else if(path.startsWith('/learn/')&&completion)completion.before(banner);else if(path.startsWith('/exam')&&feedback)feedback.after(banner);else if(path.startsWith('/results')&&result)result.after(banner);}}}
if(path.startsWith('/exam'))document.querySelectorAll('.exam-tabs button').forEach((b,i)=>{const ids=i===3?originalOutputs.map(q=>q.id):i===5?errorExamples.map(q=>q.id):['original-'+(i+1)];const done=ids.every(id=>P.practice.some(a=>a.questionId===id&&a.correct)),tried=ids.some(id=>P.practice.some(a=>a.questionId===id));b.classList.add(done?'jt-tab-complete':tried?'jt-tab-started':'jt-tab-new');const state=document.createElement('em');state.className='jt-tab-state';state.textContent=done?'✓ تمت المراجعة':tried?'◐ قيد المراجعة':'لم تبدأ بعد';b.appendChild(state);});const achievementDetails=document.getElementById('journey-achievements');if(achievementDetails&&experience.views[experienceScope()]?.details?.['journey-achievements'])achievementDetails.open=true;journeyStyleButtons();window.dispatchEvent(new CustomEvent('tgn:state'));};
