document.addEventListener('click',e=>{if(e.target.closest?.('[data-act="confirm-reset"]')){learningAwards={version:1,earned:{},initialized:false};newLearningAwards=[];lastAwardAnnouncement='';try{localStorage.removeItem(ACHIEVEMENT_KEY);}catch{}}},true);

// A single viewport transaction covers local clicks, inputs and native disclosures.
let viewportTransaction=null,viewportEpoch=0,viewportRootMinimum=null,viewportReserve=null,viewportNavigationIntent=false;
function viewportRoute(){return path.split('?')[0].replace(/\/$/,'')||'/';}
function viewportReserveNode(){
 if(!viewportReserve?.isConnected){viewportReserve=document.createElement('div');viewportReserve.id='viewport-scroll-reserve';viewportReserve.setAttribute('aria-hidden','true');viewportReserve.inert=true;document.getElementById('site').insertBefore(viewportReserve,document.getElementById('footer'));}
 return viewportReserve;
}
function viewportHoldHeight(){
 const root=document.documentElement;if(!viewportRootMinimum)viewportRootMinimum={value:root.style.getPropertyValue('min-height'),priority:root.style.getPropertyPriority('min-height')};
 root.style.setProperty('min-height',Math.max(root.scrollHeight,innerHeight)+'px','important');
}
function viewportReleaseHeight(){if(!viewportRootMinimum)return;const root=document.documentElement,old=viewportRootMinimum;viewportRootMinimum=null;if(old.value)root.style.setProperty('min-height',old.value,old.priority);else root.style.removeProperty('min-height');}
function viewportNestedState(){
 const records=[];for(const selector of ['#main .table-scroll','#main .code-window pre','#main .execution-timeline>div[role=group]','#dialog'])document.querySelectorAll(selector).forEach((node,index)=>{if(node.getClientRects().length&&(node.scrollLeft||node.scrollTop))records.push({selector,index,left:node.scrollLeft,top:node.scrollTop,text:node.tagName==='PRE'?node.textContent:''});});return records;
}
function viewportKeepSpace(y){
 const node=viewportReserveNode();node.style.height='0px';
 const intrinsic=Math.max(document.body.scrollHeight,document.body.offsetHeight,Math.ceil(document.body.getBoundingClientRect().bottom+scrollY));
 const missing=Math.max(0,Math.ceil(y+innerHeight-intrinsic));node.style.height=missing?missing+'px':'0px';
}
function viewportRestore(tx){
 if(viewportTransaction!==tx||tx.cancelled)return;
 if(tx.route!==viewportRoute()||tx.width!==innerWidth||tx.height!==innerHeight){viewportCancel(false);return;}
 viewportHoldHeight();viewportKeepSpace(tx.y);viewportReleaseHeight();window.scrollTo({left:tx.x,top:tx.y,behavior:'instant'});
 if(tx.scope===experienceScope())for(const record of tx.nested){const node=document.querySelectorAll(record.selector)[record.index];if(node?.getClientRects().length&&(!record.text||node.textContent===record.text)){node.scrollLeft=record.left;node.scrollTop=record.top;}}
}
function viewportCancel(clearSpace=false){
 const tx=viewportTransaction;if(tx)tx.cancelled=true;viewportTransaction=null;viewportEpoch++;
 if(viewportRootMinimum){viewportKeepSpace(scrollY);viewportReleaseHeight();}
 if(clearSpace&&viewportReserve)viewportReserve.style.height='0px';
}
function viewportBegin(){
 viewportNavigationIntent=false;
 if(viewportTransaction)viewportTransaction.cancelled=true;
 const tx={preserve:true,epoch:++viewportEpoch,route:viewportRoute(),scope:experienceScope(),x:scrollX,y:scrollY,width:innerWidth,height:innerHeight,nested:viewportNestedState(),cancelled:false};
 viewportTransaction=tx;viewportHoldHeight();let frames=0;
 const settle=()=>{if(viewportTransaction!==tx||tx.cancelled)return;viewportRestore(tx);if(viewportTransaction!==tx)return;if(++frames<3)requestAnimationFrame(settle);else viewportTransaction=null;};requestAnimationFrame(settle);return tx;
}
function viewportIsNavigation(control){
 if(control.tagName==='A')return true;
 if(control.dataset.ux==='lesson-step')return true;
 return ['start-exam','confirm-submit','confirm-reset','confirm-targeted','confirm-restart','mock-index','mock-next','mock-prev'].includes(control.dataset.act);
}
function initializeViewportStability(){
 document.addEventListener('click',event=>{
  const control=event.target.closest?.('a,button,summary,input,select,textarea,[role=button]');if(!control){if(document.getElementById('dialog').open&&event.target===document.getElementById('dialog'))viewportBegin();return;}if(control.disabled)return;
  if(viewportIsNavigation(control)){viewportCancel(true);viewportNavigationIntent=true;setTimeout(()=>viewportNavigationIntent=false,0);return;}
  viewportBegin();
 },true);
 for(const event of ['input','change'])document.addEventListener(event,e=>{if(e.target.matches?.('input,select,textarea'))viewportBegin();},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('dialog').open){viewportBegin();return;}const interactive=e.target.closest?.('a,button,summary,input,select,textarea,[role=button]');if(e.key==='Tab'||e.metaKey||e.ctrlKey||!interactive&&[' ','PageUp','PageDown','Home','End','ArrowUp','ArrowDown'].includes(e.key))viewportCancel(false);},true);
 for(const event of ['wheel','touchmove'])addEventListener(event,()=>viewportCancel(false),{passive:true,capture:true});
 addEventListener('resize',()=>viewportCancel(false));addEventListener('hashchange',()=>viewportCancel(true),true);
 addEventListener('scroll',()=>{
  if(viewportTransaction||viewportRootMinimum||!viewportReserve)return;const old=parseFloat(viewportReserve.style.height)||0;if(!old)return;
  const intrinsic=Math.max(document.body.scrollHeight,document.body.offsetHeight)-old,needed=Math.max(0,Math.ceil(scrollY+innerHeight-intrinsic));if(needed<old)viewportReserve.style.height=needed?needed+'px':'0px';
 },{passive:true});
}
const renderBeforeStableInteraction=render;
render=function(keep=false){
 const tx=keep&&!viewportNavigationIntent?(viewportTransaction?.route===viewportRoute()?viewportTransaction:viewportBegin()):null;
 if(tx)tx.details=experienceDetails();
 renderBeforeStableInteraction(keep);
 if(tx)viewportRestore(tx);
};


// Trace lifecycle and keyboard controls. No changes to the trace states or marking.
document.addEventListener('toggle',e=>{if(e.target.id==='loop-lab'&&e.target.isConnected&&e.target.open){rememberWorkspace();}if(e.target.id==='loop-lab'&&e.target.isConnected&&!e.target.open&&UI.playing){stopLoop();render(true);}},true);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&UI.playing){stopLoop();render(true);}});
document.addEventListener('keydown',e=>{const current=e.target.closest?.('[data-act="loop-jump"]');if(!current||e.altKey||e.ctrlKey||e.metaKey||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();let next=UI.step;if(e.key==='Home')next=0;else if(e.key==='End')next=loopStates.length-1;else next+=e.key==='ArrowLeft'||e.key==='ArrowDown'?1:-1;stopLoop();UI.step=Math.max(0,Math.min(loopStates.length-1,next));render(true);document.querySelector('[data-act="loop-jump"][data-index="'+UI.step+'"]')?.focus({preventScroll:true});});

