{const data=document.createElement("script");data.type="application/json";data.id="brand-assets";data.textContent="{\"logo\":\"data:image/png;base64,\",\"instagram\":\"data:image/png;base64,\",\"whatsapp\":\"data:image/svg+xml;base64,\"}";document.body.append(data);}
