      const track=row.querySelector('[role=progressbar]');if(track){track.setAttribute('aria-valuemin','0');track.setAttribute('aria-valuemax','3');track.setAttribute('aria-valuenow',String(lesson.step));track.setAttribute('aria-valuetext',lesson.completed?'الوحدة مكتملة':'الخطوة '+lesson.step+' من 3');if(track.firstElementChild)track.firstElementChild.style.width=lesson.step/3*100+'%';}
      const end=row.querySelector('.pm-state-icon');if(end)end.innerHTML=icon('arrow')+'<span>'+action+'</span>';
